const e=(l,d)=>({nb:l,en:d}),o="https://www.skatteetaten.no/person/folkeregister/flytte/i-norge/",U="https://www.posten.no/adressetjenester/adresseendring",s="https://www.posten.no/adressetjenester/flyttetips",W="https://www.posten.no/adressetjenester/min-adresse",V="https://www.forbrukerradet.no/forside/bolig/",A="https://www.forbrukerradet.no/forside/bolig/kjop-og-salg-av-bolig/sjekkliste-for-du-kjoper-bolig/",_="https://www.forbrukerradet.no/forside/bolig/kjop-og-salg-av-bolig/sjekkliste-selge-selv/",T="https://www.forbrukerradet.no/forside/bolig/kjop-og-salg-av-bolig/sjekkliste-megler/",c="https://www.forbrukerradet.no/forside/bolig/kjop-og-salg-av-bolig/mangler-brukt/",h="https://storage02.forbrukerradet.no/media/2025/06/forbrukerinformasjon-om-budgivning-oppdatert-pr.-1.-juli-2025.pdf",q="https://www.forbrukerradet.no/forside/bolig/husleie/sjekkliste-husleie/",f="https://www.forbrukerradet.no/forside/bolig/husleie/depositum/",g="https://www.forbrukerradet.no/forside/bolig/flyttebyra/",D="https://www.forbrukerradet.no/forside/bolig/strom/sjekkliste-for-du-velger-stromavtale/",v="https://www.forbrukerradet.no/forside/bolig/borettslag-og-sameie/",J="https://www.forbrukerradet.no/tips-og-rad-til-deg-som-skal-flytte-hjemmefra/",F="https://nef.no/wp-content/uploads/2021/11/Forbrukerinfo-nye-boligsalgsregler_nov21.pdf",C="https://www.htu.no/klage-og-tilsvar/nar-kan-du-klage",b="https://www.htu.no/vanlige-uenigheter/utleier-betaler-ikke-tilbake-depositumet",z="https://www.htu.no/klage-og-tilsvar/send-inn-klage",y="https://www.huseierne.no/alt-om-bolig/leie-ut-bolig/avslutning-av-leieforhold/oppsigelse/",u="https://www.huseierne.no/alt-om-bolig/utleie/avslutte-leieforholdet/utvask-etter-utleie-hvor-rent-skal-det-vare/",w="https://www.huseierne.no/kontrakter/overtakelsesprotokoll-ved-utleie/",a="https://www.huseierne.no/alt-om-bolig/kjope-og-selge-bolig/kjope/sjekkliste-overtakelse/",j="https://www.kartverket.no/en/property/dokumentavgift-og-gebyr/dokumentavgift-ved-overforing-av-fast-eigedom",Q="https://www.kartverket.no/en/about-kartverket/nyheter/eiendom/2024/juni/kjope-eiendom-for-forste-gang",m="https://www.helsenorge.no/en/change-doctor-gp/about",B="https://husbanken.no/person/bostotte/meld-fra-om-endringer/",k="https://www.nav.no/endringer",X="https://lanekassen.no/nb-NO/presse-og-samfunnskontakt/nyheter/lanekassen-gjennomforer-bokontroll2/",Z="https://www.ung.no/Bolig/3276_Dette_m%C3%A5_du_vite_om_leiekontrakten_din.html",$="https://www.vegvesen.no/en/about-us/about-the-organisation/about-vegvesen.no/about-your-page/your-profile/",H="https://www.bytt.no/forsikring/husforsikring/a-kodm/flyttefellen-disse-avtalene-stopper-ikke-av-seg-selv",S="https://www.forbrukertilsynet.no/wp-content/uploads/2025/11/krav-til-markedsforing-av-strom-og-valg-av-stromleverandor-i-boligovertakelsesprotokoll.pdf",ee="https://nkom.no/ekom-markedet/bytte-av-teneste-for-tilgang-til-internett",te="https://www.trondheim.kommune.no/tema/veg-vann-og-avlop/vann-og-avlop/vannmaler/",re="https://www.oslo.kommune.no/barnehage/soke-barnehageplass/",ne="https://www.oslo.kommune.no/skole-og-utdanning/skoleoversikt-og-skolekrets/bytte-grunnskole/",P="https://www.nbbl.no/for-borettslag-og-sameier/jus/hva-er-forkjopsrett/",ae="https://www.usbl.no/beboer/om-salg-av-bolig",i="https://www.finanstilsynet.no/forbrukerinformasjon/eiendomsmegling/",I="https://nef.no/slik-selger-du-bolig/hvis-du-vil-klage-pa-eiendomsmegleren/",p="https://www.smartepenger.no/boligokonomi/456-eierskifteforsikring",oe={code:"NO",currency:"NOK",native:"nb",languages:["nb","en"],reviewed:"2026-10-19",dateLocale:"nb-NO",propertyTypes:{Hus:e("Enebolig/rekkehus (selveier)","House (freehold)"),Ejerlejlighed:e("Selveierleilighet (eierseksjon)","Owned flat (eierseksjon)"),Andel:e("Borettslag (andelsleilighet)","Housing co-operative flat (borettslag)"),Leje:e("Leiebolig","Rental")},availableTypes:["Hus","Ejerlejlighed","Andel","Leje"],trackLabels:{buy:e("Mitt kjøp","My purchase"),sell:e("Mitt salg","My sale"),rentIn:e("Leie · innflytting","Renting · moving in"),rentOut:e("Leie · utflytting","Renting · moving out")},stages:[e("Forberedelse","Preparation"),e("Bud, avtale og godkjenning","Bid, contract & approval"),e("Klar til overtakelse","Ready for handover"),e("Avslutning","Closing")],contextLabels:{buy:e("Boligen jeg kjøper","The home I am buying"),sell:e("Boligen jeg selger","The home I am selling"),rentIn:e("Leieboligen jeg flytter inn i","The rental I am moving into"),rentOut:e("Leieboligen jeg flytter ut av","The rental I am leaving"),common:e("Selve flyttingen","The move itself"),incoming:e("Ny bolig","New home"),outgoing:e("Tidligere bolig","Previous home")},transport:{Selv:e("Selv","Myself"),Flyttefirma:e("Flyttebyrå","Moving company")},address:{provider:"kartverket",country:"NO"},links:{citizen:o,consumer:V}},se=[["charging",e("Ladeboks eller ladeabonnement","EV charger or charging subscription")],["children",e("Barn, skole eller barnehage","Children, school or kindergarten")],["pets",e("Kjæledyr","Pets")],["car",e("Bil, AutoPASS-avtale eller beboerparkering","Car, AutoPASS toll tag or resident parking")],["alarm",e("Alarm eller overvåkingsabonnement","Alarm or monitoring subscription")],["services",e("Serviceavtaler, f.eks. vask, snømåking eller hagehjelp","Service agreements, e.g. cleaning, snow clearing or gardening")],["benefits",e("Bostøtte, ytelser fra Nav eller annen offentlig støtte","Housing allowance, Nav benefits or other public support")],["business",e("Enkeltpersonforetak eller firma registrert på hjemmeadressen","Sole proprietorship or company registered at the home address")],["care",e("Hjemmetjenester, hjelpemidler eller løpende behandling","Home care, assistive equipment or ongoing treatment")],["association",e("Borettslag, sameie eller velforening","Housing co-operative, owners' association or residents' association")],["privacy",e("Adressesperre eller skjermet adresse","Blocked or protected address")],["proxy",e("Jeg hjelper en annen med flyttingen","I am helping someone else move")],["solar",e("Solceller eller plusskundeavtale","Solar panels or prosumer agreement")],["student",e("Student med lån eller stipend fra Lånekassen","Student with Lånekassen loan or grant")],["pension",e("Pensjon","Pension")],["firstHome",e("Første bolig eller endret husstand","First home or changed household")],["special",e("Særlige registreringer eller tillatelser","Special registrations or permits")]],t={address:e("Adresse","Address"),health:e("Helse","Health"),economy:e("Økonomi","Finances"),insurance:e("Forsikring","Insurance"),power:e("Strøm & varme","Power & heating"),charging:e("Lading","Charging"),subs:e("Abonnementer","Subscriptions"),housing:e("Boligavtaler","Housing agreements"),family:e("Familie","Family"),transport:e("Transport","Transport"),packing:e("Pakking","Packing"),handover:e("Overtakelse","Handover"),practical:e("Praktisk","Practical"),movingDay:e("Flyttedag","Moving day"),prep:e("Klargjøring","Preparation"),unpack:e("Utpakking","Unpacking")},ie=[["address",e("Meld flytting til Folkeregisteret (Skatteetaten)","Report your move to the National Population Register (Skatteetaten)"),-7,20,t.address,e("Flyttemeldingen kan sendes tidligst 31 dager før og senest 8 dager etter at du har flyttet. Det er gratis og gjøres på skatteetaten.no med ID-porten. Bruk datoen du faktisk flytter inn. Lagre kvitteringen.","The notice can be sent at the earliest 31 days before and no later than 8 days after you move. It is free and done on skatteetaten.no with ID-porten. Use the date you actually move in. Keep the receipt."),null,"date",o],["address-confirm",e("Kontroller bekreftelsen på flyttemeldingen","Check the confirmation of your move notice"),3,10,t.address,e("Sjekk adresse, bruksenhetsnummer (bolignummer), dato og hvem meldingen gjelder. Følg opp meldinger i Altinn eller din digitale postkasse.","Check the address, unit number (bolignummer), date and who the notice covers. Follow up messages in Altinn or your digital mailbox."),null,"date",o],["posten",e("Meld adresseendring til Posten og bestill ettersending","Register your new address with Posten and order mail forwarding"),-7,15,t.address,e("Posten videresender brev gratis i tolv måneder. Bestill minst fire virkedager før flytting på nett (åtte hvis du bestiller på et postkontor). Du kan melde til Posten og Folkeregisteret i samme skjema.","Posten forwards letters free for twelve months. Order at least four working days before the move online (eight at a post office). You can notify Posten and the Population Register in the same form."),null,"date",U],["contact-register",e("Oppdater digital postkasse og kontaktinformasjon","Update your digital mailbox and contact details"),-7,10,t.address,e("Sjekk at e-post og mobilnummer er riktige i Kontakt- og reservasjonsregisteret (norge.no), og at du har en digital postkasse. Offentlige vedtak om flytting, bostøtte og HTU-saker sendes dit.","Check that your e-mail and mobile number are correct in the national contact register (norge.no) and that you have a digital mailbox. Public decisions about your move, housing allowance and HTU cases are sent there.")],["mailbox",e("Sett navn på postkasse, dør og ringeklokke","Put names on the mailbox, door and doorbell"),0,15,t.address,e("Sett alle i husstanden på postkassen, også barn, slik at Posten leverer. Fjern gamle navn på begge adresser.","Put everyone in the household on the mailbox, including children, so Posten delivers. Remove old names at both addresses."),null,"date",s],["senders",e("Oppdater adresse hos avsendere og i leveringsprofiler","Update your address with senders and in delivery profiles"),-7,25,t.address,e("Gå gjennom nettbutikker, pakkebokser, matkasser, aviser og faste leveranser. Mottakerlisten i nettbanken er en god huskeliste. Sjekk åpne bestillinger til gammel adresse.","Go through web shops, parcel lockers, meal boxes, newspapers and regular deliveries. The payee list in your online bank is a good reminder. Check open orders to the old address."),null,"date",s],["employer",e("Gi arbeidsgiver og studiested beskjed","Notify your employer and place of study"),-14,15,t.address,e("Sjekk HR-/lønnssystem, reiseavtaler, hjemmekontor og eventuelt firmabetalt bredbånd.","Check the HR/payroll system, travel agreements, home office and any company-paid broadband.")],["bank",e("Kontroller adresse hos bank, pensjon og medlemsorganisasjoner","Check your address with bank, pension and membership organisations"),-7,15,t.economy,e("Mange henter adresse fra Folkeregisteret, men ikke alle. Sjekk bank, forsikring, pensjonsselskap, fagforening og foreninger.","Many fetch the address from the Population Register, but not all. Check bank, insurance, pension company, union and clubs.")],["address-followup",e("Følg opp post og avtaler som fortsatt bruker gammel adresse","Follow up mail and agreements still using the old address"),21,15,t.address,e("Rett avsendere du har oversett, og sjekk «Min adresse» hos Posten for at husstanden er riktig registrert.","Correct senders you missed and check 'Min adresse' at Posten to see that the household is registered correctly."),null,"date",W],["privacy",e("Avklar adressesperre eller skjermet adresse før flyttemelding","Clarify address protection before reporting the move"),-14,20,t.address,e("Har du sperret eller skjermet adresse, må du avklare med Skatteetaten og eventuelt politiet hvordan flyttingen skal meldes, før du sender meldingen. Ikke anta at sperringen følger med automatisk.","If your address is blocked or protected, clarify with Skatteetaten and, if relevant, the police how the move should be reported before you send the notice. Do not assume the protection follows automatically."),"privacy","date",o],["proxy",e("Avklar fullmakter for å hjelpe med flyttingen","Arrange powers of attorney to help with the move"),-42,25,t.address,e("Skaff nødvendige fullmakter hos Skatteetaten, Posten, Nav og andre. Tilgang til appen er ikke en juridisk fullmakt. Bruk egen innlogging.","Obtain the required powers of attorney from Skatteetaten, Posten, Nav and others. Access to the app is not a legal power of attorney. Use your own login."),"proxy","date",o],["special",e("Kontroller særlige registre, lisenser og tillatelser","Check special registers, licences and permits"),-28,25,t.address,e("Gå gjennom f.eks. våpenkort, jeger- og fiskerregister eller andre adresseavhengige tillatelser. Spør ansvarlig myndighet om kravene.","Review e.g. firearms licences, hunting and fishing registers or other address-dependent permits. Ask the responsible authority about the requirements."),"special"],["ad-preferences",e("Sjekk reservasjon mot reklame på ny adresse","Check advertising opt-outs at the new address"),7,10,t.address,e("Oppdater reservasjon mot uadressert reklame på postkassen og i Reservasjonsregisteret hvis du ønsker det.","Update the opt-out from unaddressed advertising on the mailbox and in the Reservation Register if you want it.")],["doctor",e("Vurder bytte av fastlege på Helsenorge","Consider changing your GP on Helsenorge"),-14,20,t.health,e("Du kan beholde fastlegen eller bytte til en ledig lege, også i en annen kommune. Du kan bytte to ganger per kalenderår, og i tillegg når du har meldt flytting til Folkeregisteret. Byttet gjelder fra den første i neste måned.","You can keep your GP or switch to one with free capacity, also in another municipality. You can switch twice per calendar year, plus once more when you have reported a move to the Population Register. The change takes effect on the first day of the next month."),null,"date",m],["journal",e("Be om overføring av journal til ny fastlege","Ask for your records to be transferred to the new GP"),14,10,t.health,e("Du har selv ansvaret for at journalen når fram til ny fastlege. Kontakt det gamle legekontoret og be om overføring. Sjekk at barn under 16 har fått riktig lege.","You are responsible for making sure your records reach the new GP. Contact the old practice and ask for a transfer. Check that children under 16 have the right doctor."),null,"date",m],["dentist",e("Gi tannlege og andre behandlere ny adresse","Give your dentist and other practitioners your new address"),-7,15,t.health,e("Gå gjennom tannlege, fysioterapeut, spesialist, apotekleveranser og andre faste kontakter.","Go through dentist, physiotherapist, specialist, pharmacy deliveries and other regular contacts.")],["medicine",e("Sørg for medisiner og nødvendig utstyr til flyttedagene","Keep medicines and essential equipment at hand for moving days"),-7,15,t.health,e("Pakk medisiner, resepter, briller og viktig utstyr slik at det er tilgjengelig under flyttingen. E-resepter følger deg, men apotek må kunne nås.","Pack medicines, prescriptions, glasses and important equipment so it is available during the move. E-prescriptions follow you, but you need a reachable pharmacy.")],["care",e("Koordiner hjemmetjenester, hjelpemidler og behandling","Coordinate home care, assistive equipment and treatment"),-42,35,t.health,e("Kontakt kommunens tildelingskontor, Nav Hjelpemiddelsentral og behandlere om overlevering, levering og startdato, så hjelpen ikke blir avbrutt. Ny kommune må fatte nytt vedtak.","Contact the municipal allocation office, Nav's assistive-technology centre and practitioners about handover, delivery and start date so help is not interrupted. A new municipality must make a new decision."),"care"],["tax",e("Sjekk skattekortet ved endrede forhold","Review your tax deduction card when circumstances change"),7,25,t.economy,e("Vurder om reisefradrag, rentefradrag, pendlerstatus eller utleie endrer skattekortet. Endre på skatteetaten.no.","Consider whether commuting deductions, interest deductions, commuter status or letting change your tax card. Update it on skatteetaten.no.")],["benefits",e("Meld endringer til Nav","Report changes to Nav"),-21,30,t.economy,e("Nav henter adressen fra Folkeregisteret, men endringer i husstand, inntekt eller boutgifter må du melde selv via nav.no/melde. Spør om ytelsen du mottar påvirkes av flyttingen.","Nav gets your address from the Population Register, but changes in household, income or housing costs must be reported by you via nav.no/melde. Ask whether the benefit you receive is affected by the move."),"benefits","date",k],["housing-benefit",e("Søk bostøtte på nytt etter flytting","Re-apply for housing allowance after moving"),-21,25,t.economy,e("Bostøtte følger ikke med automatisk: Husbanken krever at du først melder flytting til Folkeregisteret og deretter søker på nytt i Min bostøtte. Melding til Posten eller Nav er ikke nok.","Housing allowance does not carry over: Husbanken requires you to first report the move to the Population Register and then apply again in Min bostøtte. Notifying Posten or Nav is not enough."),"benefits","date",B],["moving-support",e("Undersøk hjelp til depositum eller flytteutgifter","Look into help with deposit or moving costs"),-70,25,t.economy,e("Trenger du støtte, kontakt Nav-kontoret i kommunen om økonomisk sosialhjelp eller kommunal depositumsgaranti før du inngår avtaler. Avklar vilkår og saksbehandlingstid.","If you need support, contact the municipal Nav office about financial assistance or a municipal deposit guarantee before you sign anything. Clarify conditions and processing time."),"benefits","date",k],["student",e("Oppdater bosituasjon hos Lånekassen","Update your living situation with Lånekassen"),-21,20,t.economy,e("Flyttemelding er frivillig for elever og studenter, men Lånekassen må ha riktig bosituasjon (borteboer) for at lån skal bli stipend. Oppdater på Dine sider, og ta vare på leiekontrakten til bokontrollen.","Reporting a move is voluntary for pupils and students, but Lånekassen must have your correct living situation (living away from parents) for loan-to-grant conversion. Update it on Dine sider and keep your lease for the residence check."),"student","date",X],["pension",e("Sjekk pensjon ved endret bolig eller samliv","Check pension if your home or household changes"),-21,20,t.economy,e("Endringer i sivilstatus eller samboerskap skal meldes til Nav. Sjekk også adresse hos private pensjonsleverandører.","Changes in marital status or cohabitation must be reported to Nav. Also check your address with private pension providers."),"pension","date",k],["business",e("Oppdater forretningsadresse og næringsavtaler","Update your business address and commercial agreements"),-14,30,t.economy,e("Sjekk Brønnøysundregistrene (Altinn), næringsforsikring, fakturaer, nettside og leverandører. Avklar om ny bolig eller borettslag tillater næring på adressen.","Check the Brønnøysund registers (Altinn), business insurance, invoices, website and suppliers. Clarify whether the new home or co-operative allows business at the address."),"business"],["payments",e("Kontroller gamle og nye faste betalinger","Check old and new recurring payments"),30,25,t.economy,e("Gå gjennom kontoen for doble trekk, abonnementer som fortsatt løper og manglende tilbakebetalinger. Avslutt AvtaleGiro/eFaktura først når sluttoppgjøret er klart.","Review your account for double charges, subscriptions still running and missing refunds. Cancel direct debits only once the final settlement is clear.")],["first-home",e("Avklar felles økonomi, innbo og forsikringshusstand","Agree on shared finances, contents and insurance household"),-35,30,t.economy,e("Avtal betalinger, eierskap til felles ting og hvilke forsikringer og abonnementer som skal fortsette. Samboere bør vurdere samboeravtale.","Agree on payments, ownership of shared items and which insurance policies and subscriptions continue. Cohabitants should consider a cohabitation agreement."),"firstHome"],["insurance",e("Avklar innboforsikring for begge boliger og flyttingen","Arrange contents insurance for both homes and the move"),-28,30,t.insurance,e("Innboforsikringen dekker vanligvis tingene dine under flytting, og mange selskaper dekker begge adresser i en overgangsperiode. Meld adresseendring til selskapet, bekreft datoer og hva som dekkes under transport og lagring. Lagre svaret.","Contents insurance usually covers your belongings during the move, and many insurers cover both addresses for a transition period. Report the address change to the insurer, confirm dates and what is covered in transit and storage. Keep the reply."),null,"date",g],["houseinsurance",e("Tegn husforsikring fra overtakelsesdagen","Take out building insurance from the handover date"),-28,30,t.insurance,e("Ansvaret for boligen går over til deg når nøklene overleveres og protokollen er signert. Forsikringen må gjelde fra det tidspunktet. I borettslag og sameie er bygningen ofte forsikret av laget; sjekk hva du selv må dekke.","Responsibility for the home passes to you when the keys are handed over and the protocol is signed. Insurance must apply from that moment. In co-operatives and owners' associations the building is often insured by the association; check what you must cover yourself."),"owner","accessDate",a],["houseinsurance-old",e("Meld overtakelsesdato til husforsikringen du sier opp","Give your old building insurer the handover date"),-14,15,t.insurance,e("Husforsikringen slutter ikke av seg selv ved salg. Meld overtakelsesdatoen, så får du tilbake premie for dagene etter. Ikke si opp før overtakelsen er gjennomført.","Building insurance does not end by itself when you sell. Report the handover date to get a refund for the days after. Do not cancel before the handover has taken place."),"seller","exitDate",H],["electric-old",e("Si opp strømavtale og nettleie på gammel adresse","Cancel your power contract and grid subscription at the old address"),-14,20,t.power,e("Selger avslutter sin kraftavtale og nettleieavtale fra overtakelsen; leietakere fra utflyttingsdatoen. Oppgi målerstand og dato, og be om skriftlig bekreftelse på sluttdato. Vurder å flytte en god avtale med deg i stedet for å si den opp.","The seller ends their power and grid contracts from the handover; tenants from the move-out date. Give the meter reading and date and ask for written confirmation of the end date. Consider moving a good contract with you instead of cancelling it."),null,"exitDate",a],["electric-new",e("Velg strømleverandør selv til den nye boligen","Choose your own power supplier for the new home"),-14,20,t.power,e("Nettleie følger boligen og registreres på deg; kraftleverandør velger du fritt, f.eks. via strompris.no. Du må ikke velge avtalen megleren tilbyr i overtakelsesprotokollen. Uten avtale havner du på nettselskapets leveringsplikt, som blir dyrere etter seks uker. En ny avtale kan tilbakedateres inntil 30 dager.","The grid fee follows the home and is registered to you; the power supplier is your free choice, e.g. via strompris.no. You do not have to pick the contract the agent offers in the handover protocol. Without a contract you end up on the grid company's supply obligation, which gets more expensive after six weeks. A new contract can be backdated up to 30 days."),null,"accessDate",S],["heat-old",e("Meld utflytting til fjernvarme eller felles varmeleverandør","Report your move-out to district heating or the shared heating supplier"),-28,20,t.power,e("Avklar sluttdato, avlesning og hvem som melder flyttingen. Ved felles oppvarming går avregningen ofte gjennom borettslaget, sameiet eller utleier.","Clarify the end date, reading and who reports the move. With shared heating the settlement often goes through the co-operative, owners' association or landlord."),null,"exitDate"],["heat-new",e("Avklar oppvarming og startdato i ny bolig","Clarify heating and start date in the new home"),-21,20,t.power,e("Finn ut om boligen har fjernvarme, varmepumpe, ved eller elektrisk oppvarming, og hvem som leverer og avregner. Avtal registrering og eventuell service.","Find out whether the home has district heating, a heat pump, wood or electric heating, and who supplies and bills it. Arrange registration and any servicing."),null,"accessDate"],["water",e("Avklar vann, avløp og kommunale gebyrer","Clarify water, sewage and municipal charges"),-21,15,t.power,e("Kommunale eiendomsgebyrer er knyttet til eiendommen, ikke personen: kjøper overtar saldoen, og kjøper og selger gjør opp seg imellom. Les av vannmåleren og skriv standen i overtakelsesprotokollen. Leietakere betaler normalt via husleien.","Municipal property charges follow the property, not the person: the buyer takes over the balance and buyer and seller settle between themselves. Read the water meter and record it in the handover protocol. Tenants normally pay through the rent."),null,"date",te],["meter-old",e("Fotografer og noter målerstander ved utflytting","Photograph and record meter readings when leaving"),0,20,t.power,e("Lagre målernummer, stand, dato og bilder av strøm, vann og eventuelt fjernvarme. Før standen i protokollen og noter hvem som får tallene.","Save meter number, reading, date and photos of electricity, water and any district heating. Enter the reading in the protocol and note who receives the figures."),null,"exitDate",a],["meter-new",e("Fotografer og noter målerstander ved overtakelse","Photograph and record meter readings at handover"),0,20,t.power,e("Lagre startstand, dato og bilder. Sammenlign med overtakelsesprotokollen og meld standen til nettselskap og kommune hvis de ber om det.","Save the opening reading, date and photos. Compare with the handover protocol and report the reading to the grid company and municipality if asked."),null,"accessDate",a],["final-bills",e("Kontroller sluttfakturaer for strøm, nettleie og vann","Check final invoices for power, grid fee and water"),30,20,t.power,e("Sammenlign perioder, målerstander og a konto. Følg opp tilbakebetalinger eller uventede krav. Meld strømleverandør som ikke avslutter avtalen, til Forbrukertilsynet.","Compare periods, meter readings and advance payments. Follow up refunds or unexpected charges. Report a supplier that does not close the contract to the Consumer Authority.")],["solar",e("Overdra eller avslutt plusskundeavtale og solcelleavtaler","Transfer or end your prosumer and solar agreements"),-42,30,t.power,e("Plusskunder må kjøpe og selge strøm fra samme selskap. Avklar med kraftleverandør, nettselskap og eventuell finansiering hva som følger boligen ved eierskifte.","Prosumers must buy and sell power from the same company. Clarify with the supplier, grid company and any financing what follows the home on a change of ownership."),"solar","date",D],["charge-contract",e("Si opp, flytt eller overdra ladeabonnementet","Cancel, move or transfer your charging subscription"),-42,30,t.charging,e("Finn leverandør, kundenummer, binding og oppsigelsestid. Spør om pris for oppsigelse, flytting eller overdragelse til kjøper. Lagre skriftlig svar og sluttdato.","Find the provider, customer number, lock-in and notice period. Ask what cancelling, moving or transferring to the buyer costs. Keep the written reply and end date."),"charging"],["charge-new",e("Planlegg ladeløsning på ny adresse","Plan charging at the new address"),-35,30,t.charging,e("Undersøk eksisterende ladeboks, hvem som eier den og om borettslaget/sameiet har felles ladeanlegg og egne regler. Innhent tilbud fra godkjent elektriker og book installasjon.","Check any existing charger, who owns it and whether the co-operative or association has a shared charging system and its own rules. Get quotes from an approved electrician and book installation."),"charging","accessDate"],["charge-end",e("Kontroller avslutning av ladeavtalen og siste faktura","Check the end of the charging agreement and last invoice"),14,15,t.charging,e("Lagre kvittering for returnert utstyr, bekreftet opphør og sluttoppgjør. Sjekk at en gammel avtale ikke fortsetter.","Keep receipts for returned equipment, confirmed termination and final settlement. Check that an old agreement does not continue."),"charging","exitDate"],["internet",e("Bestill flytting av bredbånd eller ny leverandør","Order broadband relocation or a new provider"),-42,25,t.subs,e("Sjekk dekning på ny adresse og bindingstid. Vil du ha nett fra dag én, bør leverandøren varsles minst tre uker før. Bytter du leverandør, er det den nye som styrer byttet, og avbrudd skal ikke vare mer enn én virkedag.","Check coverage at the new address and lock-in. If you want internet from day one, notify the provider at least three weeks ahead. If you switch provider, the new one runs the switch and downtime must not exceed one working day."),null,"date",ee],["router",e("Lever tilbake lånt ruter, tv-dekoder og annet utstyr","Return the borrowed router, TV box and other equipment"),3,20,t.subs,e("Få returinstruksjoner og frist fra leverandøren. Fotografer serienumre og ta vare på innleveringskvittering.","Get return instructions and deadline from the provider. Photograph serial numbers and keep the drop-off receipt."),null,"exitDate"],["subscriptions",e("Gå gjennom tv, strømming, mobil, aviser og andre abonnementer","Review TV, streaming, mobile, newspapers and other subscriptions"),-28,30,t.subs,e("Velg behold, flytt eller si opp for hver avtale. Sjekk adresse, husstandsvilkår og betalinger. En flytting sier ikke opp avtalene dine for deg.","Choose keep, move or cancel for each agreement. Check address, household terms and payments. Moving does not cancel your agreements for you.")],["memberships",e("Flytt eller si opp treningssenter og lokale medlemskap","Move or cancel gym and local memberships"),-35,20,t.subs,e("Gå gjennom trening, idrettslag, bibliotek og lokale foreninger. Bekreft oppsigelsestid og eventuelle nye medlemskap.","Go through gym, sports clubs, library and local associations. Confirm notice periods and any new memberships.")],["alarm",e("Flytt eller si opp alarm og overvåkingsavtale","Move or cancel alarm and monitoring agreements"),-42,25,t.subs,e("Selger sier opp sitt alarmabonnement ved overtakelsen; kjøper velger selv om samme leverandør skal brukes. Avklar utstyr, koder, overdragelse og sletting av gamle brukere.","The seller cancels their alarm subscription at handover; the buyer chooses whether to use the same provider. Clarify equipment, codes, transfer and deletion of old users."),"alarm","date",a],["services",e("Flytt eller avslutt faste serviceavtaler","Move or end regular service agreements"),-35,25,t.subs,e("Gå gjennom renhold, snømåking, hagehjelp, skadedyr, ventilasjon, feiing og andre avtaler som gjelder boligen.","Go through cleaning, snow clearing, gardening, pest control, ventilation, chimney sweeping and other agreements tied to the home."),"services"],["tenancy-end",e("Sjekk oppsigelsestid og krav ved utflytting i leiekontrakten","Check the notice period and move-out requirements in your lease"),-100,30,t.housing,e("Lovens hovedregel er tre måneders oppsigelsestid regnet til utløpet av en kalendermåned, med mindre annet er avtalt (én måned for hybel). En tidsbestemt kontrakt kan normalt ikke sies opp før tiden uten avtale. Den foreslåtte datoen i planen er ikke din kontraktfrist.","The statutory default is three months' notice counted to the end of a calendar month, unless agreed otherwise (one month for a room in the landlord's home). A fixed-term lease normally cannot be ended early without agreement. The suggested date in this plan is not your contractual deadline."),"renter","exitDate",y],["tenancy-inspection",e("Avtal utflyttingsbefaring og dokumenter boligens stand","Arrange a move-out inspection and document the condition"),-21,25,t.housing,e("Boligen skal leveres ryddet og rengjort. Finn innflyttingsprotokollen og bildene, avtal befaring med utleier og få begge til å signere protokollen ved utflytting. Utleier bør reklamere skriftlig innen rimelig tid, normalt innen 14 dager.","The home must be returned tidy and clean. Find the move-in protocol and photos, arrange an inspection with the landlord and have both sign the protocol at move-out. The landlord should object in writing within a reasonable time, normally within 14 days."),"renter","exitDate",u],["deposit",e("Be om utbetaling av depositumet","Request release of your deposit"),7,20,t.housing,e("Er dere enige, bekrefter begge utbetaling til banken. Hvis utleier ikke svarer, ber du banken om utbetaling; utleier har da fem uker på å dokumentere krav eller en sak hos HTU. Ellers skal banken betale ut til deg.","If you agree, both confirm the payout to the bank. If the landlord does not respond, ask the bank for the payout; the landlord then has five weeks to document a claim or a case at HTU. Otherwise the bank must pay you."),"renter","exitDate",b],["new-rent",e("Gå gjennom ny leiekontrakt og depositumskonto","Review the new lease and deposit account"),-21,30,t.housing,e("Bruk helst Forbrukerrådets husleiekontrakt. Depositum kan maksimalt være seks måneders leie og skal stå på egen depositumskonto i ditt navn; utleier betaler gebyret. Betal aldri til utleiers egen konto eller kontant. Sjekk oppsigelsestid, tidsbestemt/tidsubestemt og hva leien dekker.","Preferably use the Consumer Council's lease. The deposit may be at most six months' rent and must sit in a separate deposit account in your name; the landlord pays the fee. Never pay to the landlord's own account or in cash. Check notice period, fixed/open term and what the rent covers."),"newRenter","accessDate",f],["rent-in-protocol",e("Fyll ut innflyttingsprotokoll og ta bilder","Complete the move-in protocol and take photos"),0,30,t.housing,e("Gå gjennom boligen med utleier, noter skader, mangler og målerstander i en overtakelsesprotokoll og ta daterte bilder. Meld mangler skriftlig til utleier så snart du oppdager dem.","Walk through the home with the landlord, note damage, defects and meter readings in a handover protocol and take dated photos. Report defects to the landlord in writing as soon as you discover them."),"newRenter","accessDate",w],["owner-papers",e("Samle kjøpekontrakt, finansiering og oppgjørsinformasjon","Gather the purchase contract, financing and settlement details"),-35,40,t.housing,e("Kjøpesummen og omkostningene skal stå på meglers klientkonto før overtakelsen, ellers blir det ingen overtakelse. Bekreft beløp, kontonummer og dato via en kjent kanal. Samle avtaler om løsøre, nøkler og overtakelsesdato.","The purchase price and costs must be in the agent's client account before the handover, otherwise there is no handover. Confirm amount, account number and date through a known channel. Gather agreements on contents, keys and handover date."),"owner","accessDate",a],["doc-tax",e("Sett av penger til dokumentavgift og tinglysingsgebyr","Set aside money for document tax and registration fees"),-35,15,t.housing,e("Ved kjøp av selveierbolig betaler kjøper 2,5 % dokumentavgift av markedsverdien pluss tinglysingsgebyr per dokument (545 kr i 2026 for skjøte og pantedokument). Fakturaen forfaller 14 dager etter tinglysing. Borettslagsandeler er fritatt for dokumentavgift.","When buying a freehold home the buyer pays 2.5% document tax on the market value plus a registration fee per document (NOK 545 in 2026 for deed and mortgage deed). The invoice is due 14 days after registration. Co-operative shares are exempt from document tax."),"owner","accessDate",j],["sale-papers",e("Avklar leveringskrav og dokumenter ved boligsalg","Clarify delivery requirements and documents when selling"),-28,30,t.housing,e("Boligen skal være ryddet og rengjort ved overtakelsen. Gå gjennom avtaler med megler om løsøreliste, nøkler, målere, avtalte arbeider og tidspunkt. Mangler kan gi prisavslag eller tilbakehold i protokollen.","The home must be tidy and clean at handover. Go through agreements with the agent on contents list, keys, meters, agreed works and timing. Shortcomings can lead to a price reduction or holdback in the protocol."),"seller","exitDate",a],["association",e("Gi borettslag, sameie eller velforening beskjed","Notify the co-operative, owners' or residents' association"),-28,20,t.housing,e("Avklar kontaktperson, felleskostnader, inn-/utflyttingsregler, nøkkelbrikker, parkering og fellesrom. I borettslag skal styret godkjenne ny andelseier, og utleie krever styrets samtykke.","Clarify contact person, common charges, move-in/out rules, key fobs, parking and shared rooms. In a co-operative the board must approve the new shareholder, and letting requires the board's consent."),"association","date",v],["children-school",e("Ordne skoleplass og barnehageplass","Arrange school and kindergarten places"),-56,35,t.family,e("Skoleplass følger bostedsadressen (nærskole): meld flytting til kommunen og både gammel og ny skole. Barnehage søkes i kommunens portal; hovedopptak har frist 1. mars, ellers løpende opptak. Spør om plassen kan beholdes en periode etter flytting.","School place follows the home address (local-school principle): report the move to the municipality and to both the old and new school. Apply for kindergarten in the municipal portal; the main intake closes 1 March, otherwise places are allocated continuously. Ask whether a place can be kept for a period after moving."),"children","date",ne],["children-address",e("Avklar barnas adresse og delt bosted","Clarify the children's address and shared residence"),-56,25,t.family,e("Barn skal med i flyttemeldingen. Ved delt bosted eller foreldre på ulike adresser: avklar med Skatteetaten hva som kreves av samtykke, og med Nav hvordan barnetrygd og bostøtte påvirkes.","Children must be included in the move notice. With shared residence or parents at different addresses: clarify with Skatteetaten what consent is required, and with Nav how child benefit and housing allowance are affected."),"children","date",o],["children-day",e("Planlegg barnepass og barnas første kveld","Plan childcare and the children's first evening"),-14,20,t.family,e("Avtal pass på flyttedagen, transport, mat og en lett tilgjengelig kasse med kjente ting.","Arrange care on moving day, transport, food and an easily reachable box of familiar things."),"children"],["children-activities",e("Flytt fritidsaktiviteter og abonnementer for barn","Move children's leisure activities and subscriptions"),-28,20,t.family,e("Gå gjennom idrettslag, kulturskole, SFO/AKS og kontaktinformasjon. Noter utmeldings- og startdatoer og søk ny SFO-plass hos kommunen.","Go through sports clubs, music school, after-school care and contact details. Note cancellation and start dates and apply for a new after-school place with the municipality."),"children","date",re],["pets-register",e("Oppdater kjæledyrets registrering og avtaler","Update your pet's registration and agreements"),-7,20,t.family,e("Sjekk chip-registeret (f.eks. DyreID), forsikring og veterinær. Undersøk regler for husdyr i borettslag, sameie eller leiekontrakt.","Check the microchip register (e.g. DyreID), insurance and vet. Check pet rules in the co-operative, owners' association or lease."),"pets"],["pets-day",e("Avtal pass og trygg transport av kjæledyr","Arrange care and safe transport for pets"),-14,20,t.family,e("Planlegg transport, mat, medisiner og et rolig rom. Hold dyrene unna åpne dører under flyttingen.","Plan transport, food, medicines and a quiet room. Keep pets away from open doors during the move."),"pets"],["car",e("Sjekk bilforsikring, AutoPASS og parkering","Check car insurance, AutoPASS and parking"),-21,25,t.transport,e("Statens vegvesen henter adressen fra Folkeregisteret, så kjøretøyregisteret oppdateres når du melder flytting. AutoPASS-avtalen er personlig og må oppdateres selv. Søk beboerparkering i ny kommune og meld ny adresse til bilforsikringen.","The Public Roads Administration fetches your address from the Population Register, so the vehicle register updates when you report the move. The AutoPASS toll agreement is personal and must be updated by you. Apply for resident parking in the new municipality and report the new address to your car insurer."),"car","date",$],["access",e("Planlegg adkomst, parkering og eventuell heis til flyttebilen","Plan access, parking and any lift for the moving van"),-21,20,t.transport,e("Avklar innkjørsel, gårdsplass, trapper, heisbooking og om styret eller kommunen krever varsel eller tillatelse til å reservere plass.","Clarify driveway, courtyard, stairs, lift booking and whether the board or municipality requires notice or a permit to reserve space.")],["commute",e("Planlegg ny reisevei til jobb, studie og aktiviteter","Plan the new commute to work, studies and activities"),-14,20,t.transport,e("Prøv rutene og gå gjennom periodebillett, bomavtale og sykkel/bil. Husk endret kjørelengde i bilforsikringen hvis relevant.","Try the routes and review travel pass, toll agreement and bike/car. Remember to update mileage in your car insurance if relevant.")],["movers-contract",e("Kontroller flyttebyråets avtale, pris og ansvar","Check the moving company's contract, price and liability"),-21,30,t.transport,e("Håndverkertjenesteloven gjelder ikke flytting, så kontrakten avgjør. Få skriftlig totalpris, hvem som har ansvar for tingene, og eventuell øvre grense for erstatning. Sjekk firmaet i Brønnøysundregistrene og fotografer innboet før flyttingen.","The Craftsman Services Act does not cover moving, so the contract decides. Get a written total price, who is responsible for the belongings and any upper liability limit. Check the company in the Brønnøysund registers and photograph your belongings before the move."),"movers","date",g],["measure",e("Mål dører, trapper og store møbler","Measure doors, stairs and large furniture"),-28,30,t.packing,e("Sjekk at de store tingene kommer inn. Planlegg demontering, beskyttelse og plassering i ny bolig.","Check that large items fit in. Plan dismantling, protection and placement in the new home.")],["waste",e("Planlegg gjenbruk, donasjoner og avfall","Plan reuse, donations and waste"),-28,25,t.packing,e("Start tidlig med å selge, gi bort eller kaste. Sjekk kommunens gjenvinningsstasjon, åpningstider og regler for grovavfall. Klær kan leveres gratis til f.eks. Fretex.","Start early with selling, giving away or discarding. Check the municipal recycling centre, opening hours and bulky-waste rules. Clothes can be donated free to e.g. Fretex."),null,"date",s],["packing-supplies",e("Skaff esker, beskyttelse, merkelapper og flytteutstyr","Get boxes, padding, labels and moving equipment"),-35,20,t.packing,e("Vurder antall og størrelser. Merk hver eske med innhold og rom. Planlegg sekketralle, tepper, stropper og beskyttelse til skjøre ting.","Estimate quantities and sizes. Label every box with contents and room. Plan a hand truck, blankets, straps and protection for fragile items."),null,"date",s],["valuables",e("Pakk verdisaker, viktige papirer og elektronikk separat","Pack valuables, important papers and electronics separately"),-3,25,t.packing,e("Hold pass, nøkler, smykker, kontrakter og uerstattelige ting under eget oppsyn. Ta sikkerhetskopi av viktige digitale filer.","Keep passports, keys, jewellery, contracts and irreplaceable items under your own supervision. Back up important digital files.")],["appliances",e("Klargjør kjøleskap, fryser og hvitevarer for transport","Prepare fridge, freezer and appliances for transport"),-3,30,t.packing,e("Planlegg matforbruk, rengjøring, avriming og frakobling etter produsentens veiledning. Bruk fagfolk til vann- og gasstilkoblinger.","Plan food use, cleaning, defrosting and disconnection per the manufacturer's guide. Use professionals for water and gas connections.")],["loft",e("Tøm loft, kjeller, bod, garasje og andre lagringssteder","Empty loft, cellar, storage room, garage and other storage"),-7,40,t.packing,e("Gå også gjennom fellesboder, lånte ting og gjenstander hos familie eller på lager. Sjekk hva som skal følge boligen ifølge løsørelisten.","Also go through shared storage, borrowed items and things at family or in storage. Check what stays with the home according to the contents list.")],["plants",e("Planlegg trygg transport av planter, væsker og spesielle ting","Plan safe transport of plants, liquids and special items"),-7,20,t.packing,e("Avklar flyttebyråets regler og pakk etter temperatur, vekt og lekkasjerisiko. Transporter ikke farlige stoffer uten veiledning.","Check the mover's rules and pack by temperature, weight and leak risk. Do not transport hazardous materials without guidance.")],["helpers-confirm",e("Bekreft tidspunkt, roller og kontaktinfo med hjelperne","Confirm time, roles and contact details with helpers"),-3,15,t.movingDay,e("Del kjøreplan og adresser. Avtal løft, pauser, mat og hvem som har nøkler til hver bolig.","Share the schedule and addresses. Agree on lifting, breaks, food and who holds keys to each home.")],["damage",e("Gå gjennom innboet og dokumenter transportskader","Check belongings and document transport damage"),1,20,t.movingDay,e("Fotografer skader og klag skriftlig til flyttebyrået med frist på 14 dager for svar. Blir dere ikke enige, kan saken mekles hos Forbrukertilsynet. Meld også til innboforsikringen.","Photograph damage and complain in writing to the mover, asking for a reply within 14 days. If you cannot agree, the case can be mediated by the Consumer Authority. Also notify your contents insurer."),null,"date",g],["keys-old",e("Samle alle nøkler, brikker og fjernkontroller til overlevering","Collect all keys, fobs and remotes for handover"),-2,20,t.handover,e("Alle nøkler skal leveres: ytterdør, postkasse, bod, garasje og elektroniske brikker. Avtal og dokumenter antall og mottaker i protokollen.","All keys must be handed over: front door, mailbox, storage, garage and electronic fobs. Agree and document the number and recipient in the protocol."),null,"exitDate",a],["manuals",e("Overlever bruksanvisninger, servicepapirer og avtalt løsøre","Hand over manuals, service records and agreed contents"),-7,20,t.handover,e("Samle veiledninger, garantier og servicehistorikk for det som blir igjen. Fjern personlige kontoer fra smartutstyr og varmepumpe-app.","Gather manuals, warranties and service history for what stays. Remove personal accounts from smart devices and heat-pump apps.")],["safety",e("Finn stoppekran, sikringsskap og test røykvarslere","Find the stopcock, fuse box and test smoke alarms"),1,20,t.handover,e("Bli kjent med boligens installasjoner. Eier har ansvar for røykvarslere og slokkeutstyr. Finn ventilasjon, varmepumpe og eventuelle smarthus-systemer.","Get to know the home's installations. The owner is responsible for smoke alarms and fire extinguishers. Locate ventilation, heat pump and any smart-home systems."),null,"accessDate",a],["waste-new",e("Finn renovasjonsordning og tømmedager på ny adresse","Find waste collection and pickup days at the new address"),3,15,t.practical,e("Sjekk kommunens eller renovasjonsselskapets tømmekalender og sorteringsregler, og hent eventuelle beholdere eller nøkkelbrikker til avfallsbrønner.","Check the municipal or waste company's collection calendar and sorting rules, and collect any bins or fobs for underground containers.")],["empty-check",e("Ta sluttbilder og sjekk alle rom ved utflytting","Take final photos and check every room when leaving"),0,25,t.handover,e("Sjekk skap, vinduskarmer, bod, balkong og uteareal. Lagre bilder og bekreftelse på nøkler og overlevering.","Check cupboards, window sills, storage, balcony and outdoor areas. Keep photos and confirmation of keys and handover."),null,"exitDate"],["locks",e("Avklar nøkler, låser og digitale tilganger i ny bolig","Sort out keys, locks and digital access in the new home"),1,20,t.handover,e("Vurder omkoding etter avtale med eier eller utleier. Nullstill smarthus-tilganger og sørg for tilgang til postkasse og fellesdører.","Consider re-keying by agreement with the owner or landlord. Reset smart-home access and make sure you can open the mailbox and shared doors."),null,"accessDate"],["handover-defects",e("Følg opp feil, mangler og avtaler fra overtakelsen","Follow up defects, shortcomings and agreements from the handover"),1,25,t.handover,e("Kjøper: reklamer skriftlig til selger og boligselgerforsikringen så snart du oppdager noe; du dekker de første 10 000 kr selv, og alt er foreldet etter fem år. Leietaker: meld mangler skriftlig til utleier straks. Lagre svaret.","Buyer: complain in writing to the seller and the seller's insurer as soon as you discover something; you bear the first NOK 10,000 yourself and all claims lapse after five years. Tenant: report defects to the landlord in writing immediately. Keep the reply."),null,"accessDate",c],["neighbours",e("Orienter naboer om flytting og adkomst","Let neighbours know about the move and access"),-7,10,t.practical,e("Avtal hensyn til oppgang, heis, parkering og støy, og del gjerne et kontaktnummer.","Agree on consideration for stairwell, lift, parking and noise, and share a contact number.")],["clean-final",e("Fullfør flyttevask og avtalt istandsetting","Finish the move-out cleaning and agreed repairs"),-2,60,t.prep,e("Boligen skal være ryddet og rengjort: ovn, ventilator, skap innvendig og utvendig, bad, vinduer, bod og balkong. Du trenger ikke vaskebyrå, men resultatet må være like godt. Ta vare på kvitteringer.","The home must be tidy and cleaned: oven, extractor, cupboards inside and out, bathroom, windows, storage and balcony. You do not need a cleaning firm, but the result must be as good. Keep receipts."),null,"exitDate",u],["packing-return",e("Lever tilbake lånte esker, nøkler og flytteutstyr","Return borrowed boxes, keys and moving equipment"),14,20,t.unpack,e("Avklar returfrister og ta vare på kvitteringer. Noter eventuelt depositum som skal betales tilbake.","Clarify return deadlines and keep receipts. Note any deposit to be refunded.")]],le={rent:q,rentIn:w,rentOut:y,sale:_,contract:A,approval:h,settle:Q,refund:a,deposit:f,defects:c,megler:T,coop:P,coopSale:ae,finanstilsynet:i,insurance:p,power:S,docTax:j,htu:C,htuDeposit:b,cleaning:u,lease:Z,brl:v,avhl:F,insuranceEnd:H},de=[["buy",0,"budget",e("Skaff finansieringsbevis og sett en ramme","Get a financing certificate and set your limit"),e("Deg + bank","You + bank"),e("Banken vurderer hvor mye du kan låne. Hovedregelen er 15 % egenkapital og maks fem ganger inntekt. Regn også på omkostninger (dokumentavgift, gebyrer), en periode med to boliger og en renteøkning.","The bank assesses how much you can borrow. The main rule is 15% equity and at most five times income. Also budget for costs (document tax, fees), a period with two homes and a rate rise."),e("Finansieringsbevis og budsjett","Financing certificate and budget"),"contract"],["buy",0,"help",e("Bestem hvem som hjelper deg","Decide who helps you"),e("Deg","You"),e("Megleren er engasjert av selger, men har omsorgsplikt overfor begge. Vurder egen bygningssakkyndig til befaring, advokat ved kompliserte forhold og om du vil ha boligkjøperforsikring. Ta med noen som har kjøpt bolig før på visning.","The agent is engaged by the seller but owes a duty of care to both. Consider your own building surveyor for an inspection, a lawyer for complex matters and whether you want buyer's insurance. Bring someone who has bought before to the viewing."),e("Liste over rådgivere og avtaler","List of advisers and agreements"),"contract"],["buy",0,"inspect",e("Les salgsoppgave, tilstandsrapport og egenerklæring","Read the prospectus, condition report and seller's declaration"),e("Deg + eventuell sakkyndig","You + surveyor if any"),e("Du regnes for å kjenne alt som står tydelig i salgsdokumentene, selv om du ikke har lest dem. Se særlig på tilstandsgrader, fukt i bad og kjøkken, el-anlegg, tak og drenering. Spør megler skriftlig om alt som er uklart, og be om dokumentasjon på arbeid.","You are deemed to know everything clearly stated in the sales documents, even if you did not read them. Look especially at condition grades, moisture in bathroom and kitchen, electrics, roof and drainage. Ask the agent in writing about anything unclear and request documentation of works."),e("Spørsmål besvart skriftlig","Questions answered in writing"),"contract"],["buy",0,"association",e("Gå gjennom borettslagets eller sameiets økonomi","Review the co-operative's or association's finances"),e("Deg + bank","You + bank"),e("Be om vedtekter, husordensregler, regnskap, budsjett, årsmøtereferat og vedlikeholdsplan. Sjekk fellesgjeld (inngår i totalprisen og i bankens låneberegning), avdragsfrihet, planlagte arbeider, sikringsordning for felleskostnader og om det er forkjøpsrett.","Ask for bylaws, house rules, accounts, budget, AGM minutes and maintenance plan. Check shared debt (part of the total price and the bank's loan calculation), interest-only periods, planned works, the guarantee scheme for common charges and whether there is a right of first refusal."),e("Gjennomgått foreningsøkonomi","Reviewed association finances"),"brl",["Ejerlejlighed","Andel"]],["buy",0,"offer",e("Forbered budet","Prepare your bid"),e("Deg + bank","You + bank"),e("Bud er bindende når det er formidlet til selger, og det er ingen angrerett. Sett maksimumspris, finansieringsplan, akseptfrist, ønsket overtakelsesdato og eventuelle forbehold skriftlig. Bud med forbehold blir normalt ikke akseptert før forbeholdet er avklart. By ikke på flere boliger samtidig.","A bid is binding once passed to the seller, and there is no cooling-off right. Put your maximum price, financing plan, acceptance deadline, preferred handover date and any conditions in writing. Conditional bids are normally not accepted until the condition is cleared. Do not bid on several homes at once."),e("Skriftlig bud og forutsetninger","Written bid and assumptions"),"approval"],["buy",1,"terms",e("Gå gjennom kjøpekontrakten før signering","Review the purchase contract before signing"),e("Deg + megler","You + agent"),e("Bindende avtale oppstår når selger aksepterer budet; megler skriver deretter kontrakt. Kontroller pris, overtakelsesdato, løsøreliste, avtalte arbeider og hva som skjer ved forsinkelse. Få uklare vilkår forklart før du signerer.","A binding agreement arises when the seller accepts the bid; the agent then drafts the contract. Check price, handover date, contents list, agreed works and what happens on delay. Have unclear terms explained before you sign."),e("Gjennomgått kontrakt","Reviewed contract"),"finanstilsynet"],["buy",1,"forkjop",e("Vent på avklaring av forkjøpsrett","Wait for the right of first refusal to be cleared"),e("Boligbyggelag + megler","Housing federation + agent"),e("Er forkjøpsretten ikke forhåndsavklart, har laget inntil 20 dager fra salget meldes til å avklare om et medlem med lengre ansiennitet trer inn i budet ditt. Skjer det, er du løst fra avtalen. Avvent oppsigelse av nåværende bolig til fristen er ute.","If the right of first refusal was not cleared in advance, the federation has up to 20 days from notification of the sale to decide whether a member with longer seniority steps into your bid. If so, you are released from the agreement. Do not give notice on your current home until the deadline has passed."),e("Bekreftelse på at forkjøpsrett ikke er brukt","Confirmation that the right was not exercised"),"coop",["Andel"]],["buy",1,"forbehold",e("Følg opp forbehold i budet","Follow up conditions in your bid"),e("Deg + bank + megler","You + bank + agent"),e("Har du tatt forbehold om finansiering eller salg av egen bolig, må du få det avklart skriftlig innen fristen. Et forbehold som ikke er oppfylt, kan brukes til å gå fra avtalen; et oppfylt forbehold gjør avtalen endelig.","If you made your bid conditional on financing or selling your own home, get it cleared in writing within the deadline. An unfulfilled condition may allow you to withdraw; a fulfilled one makes the agreement final."),e("Skriftlig avklaring","Written clearance"),"approval"],["buy",1,"buyerins",e("Ta stilling til boligkjøperforsikring","Decide on buyer's insurance"),e("Deg","You"),e("Boligkjøperforsikring dekker juridisk hjelp hvis du senere må reklamere mot selger eller selgers boligselgerforsikring. Den må normalt tegnes senest ved kontraktsignering. Vurder pris mot egen rettshjelpsdekning.","Buyer's insurance covers legal help if you later need to claim against the seller or the seller's insurer. It must normally be taken out by contract signing. Weigh the price against the legal cover you already have."),e("Beslutning og eventuell polise","Decision and any policy"),"insurance"],["buy",2,"payment",e("Betal kjøpesum og omkostninger til klientkonto","Pay the purchase price and costs into the client account"),e("Bank + megler","Bank + agent"),e("Hele kjøpesummen og omkostningene skal stå på meglers klientkonto før overtakelsen; uten betaling blir det ingen overtakelse. Bekreft kontonummer via en kjent kanal, aldri bare fra e-post. Banken utbetaler lånet mot pantedokument.","The full price and costs must be in the agent's client account before the handover; without payment there is no handover. Confirm the account number through a known channel, never from e-mail alone. The bank disburses the loan against the mortgage deed."),e("Bankens kvitteringer","Bank receipts"),"finanstilsynet"],["buy",2,"deed",e("Følg skjøte, tinglysing og dokumentavgift","Follow the deed, registration and document tax"),e("Megler + Kartverket","Agent + Land Registry"),e("Megler tinglyser skjøtet og bankens pantedokument hos Kartverket, vanligvis elektronisk. Du betaler 2,5 % dokumentavgift av markedsverdien og tinglysingsgebyr per dokument; fakturaen forfaller 14 dager etter tinglysing og kan ikke utsettes.","The agent registers the deed and the bank's mortgage deed with the Land Registry, usually electronically. You pay 2.5% document tax on the market value plus a registration fee per document; the invoice is due 14 days after registration and cannot be deferred."),e("Tinglysingsstatus og faktura","Registration status and invoice"),"docTax",["Hus","Ejerlejlighed"]],["buy",2,"coop",e("Få godkjenning og eierskifte i borettslaget på plass","Get approval and the share transfer in the co-operative"),e("Forretningsfører + styret + megler","Manager + board + agent"),e("Styret har 20 dager på å godkjenne deg som ny andelseier. Du må ofte være medlem i boligbyggelaget før eierskiftet gjennomføres. Andelen tinglyses hos Kartverket uten dokumentavgift, men laget krever eierskiftegebyr. Felleskostnader løper fra overtakelsen.","The board has 20 days to approve you as the new shareholder. You often must be a member of the housing federation before the transfer completes. The share is registered with the Land Registry without document tax, but the co-operative charges a transfer fee. Common charges run from handover."),e("Godkjent eierskifte","Approved transfer"),"coopSale",["Andel"]],["buy",2,"insurance",e("Tegn husforsikring og innboforsikring fra overtakelsen","Take out building and contents insurance from handover"),e("Deg + forsikringsselskap","You + insurer"),e("Når nøklene er overlevert og protokollen signert, er boligen ditt ansvar. Forsikringen må gjelde fra det tidspunktet. I borettslag og sameie er bygningen ofte forsikret gjennom laget; avklar hva du må dekke selv.","Once the keys are handed over and the protocol signed, the home is your responsibility. Insurance must apply from that moment. In co-operatives and owners' associations the building is often insured through the association; clarify what you must cover yourself."),e("Polise med startdato","Policy with start date"),"refund"],["buy",2,"electricity",e("Velg strømleverandør selv før overtakelsen","Choose your own power supplier before handover"),e("Deg","You"),e("Du kan avslå strømavtalen som tilbys i overtakelsesprotokollen; megler kan ikke bestille strøm på dine vegne uten fullmakt. Bestill selv en åpen spotprisavtale fra overtakelsesdatoen, eller få nettselskapets leveringsplikt midlertidig.","You may decline the power contract offered in the handover protocol; the agent cannot order power on your behalf without authority. Order an open spot-price contract yourself from the handover date, or fall back temporarily on the grid company's supply obligation."),e("Bekreftet strømavtale","Confirmed power contract"),"power"],["buy",2,"handover",e("Gjennomfør overtakelsen med protokoll","Carry out the handover with a protocol"),e("Deg + selger + megler","You + seller + agent"),e("Sett av ca. 90 minutter. Sjekk at boligen er ryddet og rengjort, at avtalt løsøre er der, alle nøkler, ingen nye skader, og test tekniske anlegg. Noter strøm- og vannmåler. Uenighet om mangler føres i protokollen; større beløp kan holdes tilbake på meglers klientkonto.","Set aside about 90 minutes. Check that the home is tidy and clean, agreed contents are present, all keys, no new damage, and test technical systems. Record electricity and water meters. Disputes about defects go in the protocol; larger amounts can be held back in the agent's client account."),e("Signert overtakelsesprotokoll og bilder","Signed handover protocol and photos"),"refund"],["buy",3,"settlement",e("Kontroller oppgjørsoppstillingen","Check the settlement statement"),e("Deg + megler","You + agent"),e("Megler sender oppgjørsoppstilling til begge parter. Kontroller kjøpesum, omkostninger, eventuelt tilbakeholdt beløp og renter på klientkonto. Be om forklaring på avvik.","The agent sends a settlement statement to both parties. Check the price, costs, any holdback and interest on the client account. Ask for an explanation of discrepancies."),e("Godkjent oppgjørsoppstilling","Approved settlement statement"),"finanstilsynet"],["buy",3,"defects",e("Reklamer på mangler innen rimelig tid","Complain about defects within a reasonable time"),e("Deg + selgers forsikring","You + seller's insurer"),e("Reklamer skriftlig til selger og boligselgerforsikringen så snart du oppdager en mangel; absolutt frist er fem år. Du dekker selv de første 10 000 kr. Forhold som er opplyst i tilstandsrapporten, kan du ikke klage på. Uenighet med forsikringen kan bringes inn for Finansklagenemnda.","Complain in writing to the seller and the seller's insurer as soon as you discover a defect; the absolute limit is five years. You bear the first NOK 10,000. You cannot claim for matters disclosed in the condition report. Disputes with the insurer can go to the Financial Complaints Board."),e("Sendt reklamasjon og svar","Sent complaint and reply"),"defects"],["buy",3,"close",e("Sjekk at du står som eier i grunnboken","Check that you are the registered owner"),e("Deg","You"),e("Logg inn hos Kartverket (Eiendomsregisteret) og se at du står som hjemmelshaver, at bankens pant er tinglyst og at selgers lån er slettet. Arkiver kontrakt, protokoll, tilstandsrapport og oppgjør.","Log in at the Land Registry and check that you are the registered title holder, that your bank's mortgage is registered and the seller's loan is deleted. Archive the contract, protocol, condition report and settlement."),e("Utskrift fra grunnboken","Land register extract"),"settle"],["sell",0,"proceeds",e("Beregn hva du sitter igjen med","Calculate your net proceeds"),e("Deg + bank / megler","You + bank / agent"),e("Trekk fra restgjeld, meglerhonorar, tilstandsrapport, boligselgerforsikring, markedsføring og eventuelt eierskiftegebyr. Regn også på lavere salgspris og lengre salgstid.","Deduct remaining debt, agent's fee, condition report, seller's insurance, marketing and any transfer fee. Also calculate a lower price and longer selling time."),e("Provenyberegning","Proceeds calculation"),"sale"],["sell",0,"agent",e("Velg megler eller selg selv","Choose an agent or sell yourself"),e("Deg","You"),e("Innhent tilbud fra flere meglere og sammenlign totalpris og hva som inngår. Honoraret er forhandlbart: provisjon, fastpris eller timepris. Oppdragsavtalen skal være skriftlig, maks seks måneder, og si hva du betaler hvis boligen ikke blir solgt.","Get quotes from several agents and compare total price and what is included. The fee is negotiable: commission, fixed price or hourly. The engagement agreement must be in writing, at most six months, and state what you pay if the home is not sold."),e("Signert oppdragsavtale","Signed engagement agreement"),"megler"],["sell",0,"report",e("Bestill tilstandsrapport og fyll ut egenerklæring","Order a condition report and complete the seller's declaration"),e("Deg + bygningssakkyndig","You + building surveyor"),e("Boliger kan ikke selges «som den er» til forbrukere. En tilstandsrapport etter forskriften flytter ansvaret for det som er beskrevet over på kjøper. Svar ærlig i egenerklæringen; feil svar gir ansvar. Samle dokumentasjon på utført arbeid.","Homes cannot be sold 'as is' to consumers. A condition report meeting the regulation shifts responsibility for what is described onto the buyer. Answer the seller's declaration honestly; wrong answers create liability. Gather documentation of works done."),e("Godkjent tilstandsrapport og egenerklæring","Approved condition report and declaration"),"avhl"],["sell",0,"sellerins",e("Vurder boligselgerforsikring","Consider seller's insurance"),e("Deg + megler","You + agent"),e("Forsikringen dekker helt eller delvis ansvaret ditt etter avhendingslova i fem år og håndterer reklamasjoner fra kjøper. Prisen er en prosent av salgssummen. Den må tegnes før salget og forutsetter korrekt egenerklæring.","The insurance covers all or part of your liability under the Sale of Property Act for five years and handles buyer complaints. The price is a percentage of the sale price. It must be taken out before the sale and requires a correct declaration."),e("Beslutning og eventuell polise","Decision and any policy"),"insurance"],["sell",0,"association",e("Varsle forretningsfører og avklar forkjøpsrett","Notify the manager and clarify the right of first refusal"),e("Deg + forretningsfører + megler","You + manager + agent"),e("I borettslag med forkjøpsrett velger du forhåndsavklaring (utlyses før salg, gebyr hvis retten ikke brukes) eller fastprisavklaring etter budrunden (20 dagers frist). Avklar restanser på felleskostnader og eierskiftegebyr. Sameier: bestill opplysninger fra forretningsfører.","In a co-operative with first-refusal rights choose advance clearance (advertised before sale, fee if not used) or fixed-price clearance after bidding (20-day deadline). Clear any arrears on common charges and the transfer fee. Owners' associations: order information from the manager."),e("Foreningsopplysninger og utlysning","Association information and notice"),"coopSale",["Ejerlejlighed","Andel"]],["sell",0,"market",e("Gjør salgsoppgave, bilder og visning klar","Prepare the prospectus, photos and viewing"),e("Deg + megler","You + agent"),e("Salgsoppgaven skal gi riktige og fullstendige opplysninger; du og megler er hver for dere ansvarlige. Beskriv både styrker og svakheter, og lag en tydelig liste over hva som følger med.","The prospectus must give correct and complete information; you and the agent are each responsible. Describe both strengths and weaknesses, and make a clear list of what is included."),e("Godkjent salgsoppgave","Approved prospectus"),"sale"],["sell",1,"negotiate",e("Vurder bud og akseptfrister","Assess bids and acceptance deadlines"),e("Deg + megler","You + agent"),e("Alle bud og aksept skal være skriftlige, og megler fører budjournal. Du står fritt til å avslå, også det høyeste budet, men et akseptert bud er en bindende avtale. Megler kan ikke formidle bud med frist før kl. 12.00 første virkedag etter siste annonserte visning.","All bids and acceptances must be in writing, and the agent keeps a bid journal. You are free to reject any bid, even the highest, but an accepted bid is a binding agreement. The agent cannot pass on bids with a deadline before 12:00 on the first working day after the last advertised viewing."),e("Akseptert bud og budjournal","Accepted bid and bid journal"),"approval"],["sell",1,"contract",e("Gå gjennom og signer kjøpekontrakten","Review and sign the purchase contract"),e("Deg + megler","You + agent"),e("Kontroller at kontrakten gjengir budet, overtakelsesdato, løsøre og eventuelle avtalte arbeider. Du kan ikke trekke deg etter akseptert bud; få konsekvenser forklart før signering.","Check that the contract reflects the bid, handover date, contents and any agreed works. You cannot withdraw after an accepted bid; have the consequences explained before signing."),e("Signert kontrakt","Signed contract"),"finanstilsynet"],["sell",1,"forkjop",e("Avvent forkjøpsrettsfristen","Wait out the first-refusal deadline"),e("Boligbyggelag","Housing federation"),e("Ved fastprisavklaring har laget 20 dager fra skriftlig salgsmelding til å avklare forkjøpsrett. Bruker et medlem retten, trer vedkommende inn i det aksepterte budet, og kjøper løses fra avtalen. Ikke bind deg til ny bolig før fristen er ute.","With fixed-price clearance the federation has 20 days from written notice of the sale to clear the right. If a member uses it, they step into the accepted bid and the buyer is released. Do not commit to a new home until the deadline has passed."),e("Avklaring fra laget","Clearance from the federation"),"coop",["Andel"]],["sell",2,"works",e("Fullfør avtalte arbeider og løsørelisten","Finish agreed works and the contents list"),e("Deg","You"),e("Gjør det avtalte og ta vare på dokumentasjon. Avklar skriftlig hva som blir igjen og hva du tar med. Boligen skal være ryddet og rengjort ved overtakelsen.","Do what was agreed and keep documentation. Clarify in writing what stays and what you take. The home must be tidy and clean at handover."),e("Bilder og kvitteringer","Photos and receipts"),"refund"],["sell",2,"bank",e("Følg innfrielse og oppgjør","Follow loan redemption and settlement"),e("Bank + megler","Bank + agent"),e("Megler innfrir lånet ditt fra klientkontoen, sletter pant og tinglyser skjøtet. Du får normalt pengene én til to uker etter overtakelsen, når skjøtet er kommet i retur. Nøkkeloverlevering er ikke i seg selv utbetaling.","The agent redeems your loan from the client account, deletes the mortgage and registers the deed. You normally receive the money one to two weeks after handover, once the deed is returned. Handing over keys is not in itself payment."),e("Status fra megler og bank","Status from agent and bank"),"refund"],["sell",2,"handover",e("Lever boligen med protokoll","Hand over the home with a protocol"),e("Deg + kjøper + megler","You + buyer + agent"),e("Gjennomgå boligen sammen, les av strøm og vann, lever alle nøkler og signer overtakelsesprotokollen. Si opp strøm- og nettleieavtale og alarm fra overtakelsesdatoen. Meglers oppgjørsavdeling bruker protokollen til å frigi oppgjøret.","Walk through the home together, read electricity and water meters, hand over all keys and sign the handover protocol. Cancel your power, grid and alarm agreements from the handover date. The agent's settlement team uses the protocol to release payment."),e("Signert protokoll","Signed protocol"),"refund"],["sell",3,"settlement",e("Kontroller oppgjørsoppstilling og utbetaling","Check the settlement statement and payout"),e("Deg + megler","You + agent"),e("Sammenlign oppgjørsoppstillingen med forventet proveny: salgssum, innfridd lån, honorar, utlegg, eventuelt tilbakeholdt beløp og renter. Be om forklaring på avvik.","Compare the settlement statement with your expected proceeds: sale price, redeemed loan, fee, expenses, any holdback and interest. Ask for an explanation of discrepancies."),e("Oppgjørsoppstilling og kontoutskrift","Settlement statement and bank statement"),"finanstilsynet"],["sell",3,"insurance-end",e("Avslutt husforsikring med overtakelsesdato","End building insurance with the handover date"),e("Deg + forsikringsselskap","You + insurer"),e("Forsikringen opphører ikke automatisk. Meld overtakelsesdatoen og få refundert premie for dagene etter. Behold innboforsikringen på ny adresse.","The policy does not end automatically. Report the handover date and get a premium refund for the days after. Keep contents insurance at the new address."),e("Bekreftet opphør og refusjon","Confirmed termination and refund"),"insuranceEnd"],["sell",3,"close",e("Arkiver saken og vær klar for reklamasjoner","Archive the case and be ready for complaints"),e("Deg","You"),e("Kjøper kan reklamere i inntil fem år. Ta vare på salgsoppgave, tilstandsrapport, egenerklæring, kontrakt, protokoll og oppgjør. Har du boligselgerforsikring, skal reklamasjoner sendes dit straks.","The buyer can complain for up to five years. Keep the prospectus, condition report, declaration, contract, protocol and settlement. If you have seller's insurance, complaints must be sent there immediately."),e("Samlet saksmappe","Complete case file"),"defects"],["rentIn",0,"budget",e("Beregn innflyttingsutgifter og depositum","Calculate move-in costs and deposit"),e("Deg","You"),e("Depositum kan maksimalt være seks måneders leie (tre er vanlig) og avtales ved kontraktsinngåelse. Regn også med husleie, strøm hvis det er avtalt, bredbånd, innboforsikring og eventuell dobbel boutgift.","The deposit may be at most six months' rent (three is common) and is agreed at signing. Also budget for rent, electricity if agreed, broadband, contents insurance and any overlapping housing cost."),e("Innflyttingsbudsjett","Move-in budget"),"deposit"],["rentIn",0,"verify",e("Sjekk boligen og utleieren","Check the home and the landlord"),e("Deg","You"),e("Se boligen, finn ut hvem du inngår avtale med og om utleier eier boligen. I kollektiv bør alle signere, ellers er den som signerer alene ansvarlig. Be om Forbrukerrådets husleiekontrakt.","View the home, find out who you are contracting with and whether the landlord owns it. In a shared flat everyone should sign, otherwise the one signing is solely liable. Ask for the Consumer Council's lease."),e("Kontakt og avtalegrunnlag","Contact and basis for agreement"),"rent"],["rentIn",1,"contract",e("Gå gjennom leiekontrakten","Review the lease"),e("Deg","You"),e("Sjekk om avtalen er tidsbestemt eller tidsubestemt, oppsigelsestid, hva leien dekker (strøm og vann kan bare komme i tillegg hvis det står i kontrakten), husordensregler og depositum. Leien kan kun justeres etter KPI én gang i året med én måneds varsel.","Check whether the lease is fixed-term or open-ended, the notice period, what the rent covers (electricity and water can only be extra if the contract says so), house rules and deposit. Rent can only be adjusted by CPI once a year with one month's notice."),e("Gjennomgått kontrakt","Reviewed contract"),"lease"],["rentIn",1,"deposit",e("Få depositumskonto i ditt navn","Get a deposit account in your name"),e("Deg + utleier + bank","You + landlord + bank"),e("Depositumet skal stå på egen sperret konto i ditt navn, der ingen kan ta ut penger alene. Utleier betaler gebyret, og rentene er dine. Betal aldri depositum til utleiers egen konto eller kontant; det er ulovlig og kan kreves tilbake.","The deposit must sit in a separate blocked account in your name, which neither party can draw on alone. The landlord pays the fee and the interest is yours. Never pay the deposit to the landlord's own account or in cash; it is unlawful and can be reclaimed."),e("Kontobekreftelse fra banken","Account confirmation from the bank"),"deposit"],["rentIn",2,"inspection",e("Gjennomfør innflyttingsbefaring med protokoll","Do a move-in inspection with a protocol"),e("Deg + utleier","You + landlord"),e("Bruk en overtakelsesprotokoll for utleie: tilstand, innhold, nøkler og målerstander. Ta daterte bilder av alle skader. Protokollen er beviset ditt når du flytter ut.","Use a rental handover protocol: condition, contents, keys and meter readings. Take dated photos of all damage. The protocol is your evidence when you move out."),e("Signert protokoll og bilder","Signed protocol and photos"),"rentIn"],["rentIn",2,"defects",e("Meld mangler skriftlig til utleier","Report defects to the landlord in writing"),e("Deg","You"),e("Send en liste over mangler så snart du oppdager dem, med bilder. Ikke vent til flyttingen er ferdig. Be om bekreftelse på mottak og avtal frist for utbedring.","Send a list of defects as soon as you discover them, with photos. Do not wait until the move is finished. Ask for confirmation of receipt and agree a deadline for repairs."),e("Sendt mangelliste og svar","Sent list of defects and reply"),"rentIn"],["rentIn",3,"follow",e("Følg opp utbedringer og første betaling","Follow up repairs and the first payment"),e("Deg + utleier","You + landlord"),e("Sjekk at første husleie og depositum er riktig registrert. Blir dere ikke enige om mangler eller leie, kan saken sendes til Husleietvistutvalget (HTU), som dekker hele landet.","Check that the first rent and deposit are correctly registered. If you cannot agree on defects or rent, the case can go to the Rent Disputes Tribunal (HTU), which covers the whole country."),e("Avklarte utestående punkter","Resolved open items"),"htu"],["rentOut",0,"notice",e("Sjekk oppsigelsestid og om avtalen er tidsbestemt","Check the notice period and whether the lease is fixed-term"),e("Deg","You"),e("Hovedregelen er tre måneders oppsigelsestid til utløpet av en kalendermåned, men kontrakten kan si noe annet. En tidsbestemt avtale kan normalt ikke sies opp før utløp med mindre det er avtalt. Siste betalingsdag og utflyttingsdag er ikke nødvendigvis samme dato.","The default is three months' notice to the end of a calendar month, but the contract may say otherwise. A fixed-term lease normally cannot be ended early unless agreed. The last payment day and move-out day are not necessarily the same date."),e("Bekreftede datoer","Confirmed dates"),"rentOut"],["rentOut",1,"terminate",e("Si opp skriftlig og få bekreftelse","Give notice in writing and get confirmation"),e("Deg + utleier","You + landlord"),e("Du som leietaker kan si opp uten begrunnelse, men gjør det skriftlig så du kan dokumentere datoen. Be utleier bekrefte sluttdato og tidspunkt for befaring. Oppgi ny adresse for depositumsoppgjøret.","As tenant you can give notice without a reason, but do it in writing so you can prove the date. Ask the landlord to confirm the end date and inspection time. Give your new address for the deposit settlement."),e("Oppsigelse og svar","Notice and reply"),"rentOut"],["rentOut",2,"prepare",e("Forbered flyttevask og tilbakelevering","Prepare the move-out cleaning and return"),e("Deg","You"),e("Boligen skal leveres ryddet og rengjort i samme stand som ved innflytting, med normal slitasje. Finn innflyttingsprotokollen og bildene før du bestiller arbeid.","The home must be returned tidy and cleaned in the same condition as at move-in, allowing for normal wear. Find the move-in protocol and photos before ordering any work."),e("Plan for vask og utbedring","Plan for cleaning and repairs"),"cleaning"],["rentOut",2,"inspection",e("Delta på utflyttingsbefaring og lever nøkler","Attend the move-out inspection and hand over keys"),e("Deg + utleier","You + landlord"),e("Gå gjennom boligen sammen, les av målere, lever alle nøkler og signer protokollen. Noter uenigheter i protokollen. Utleier bør reklamere skriftlig innen rimelig tid, normalt 14 dager.","Walk through together, read meters, hand over all keys and sign the protocol. Note disagreements in the protocol. The landlord should object in writing within a reasonable time, normally 14 days."),e("Signert utflyttingsprotokoll","Signed move-out protocol"),"rentIn"],["rentOut",3,"deposit",e("Få depositumet utbetalt","Get the deposit paid out"),e("Deg + bank + utleier","You + bank + landlord"),e("Er dere enige, bekrefter begge til banken. Hvis ikke, ber du banken om utbetaling; utleier har fem uker på å dokumentere ubetalt leie i samme bank eller en sak hos HTU/forliksrådet. Uten det skal banken betale ut til deg. Ulovlig depositum kan kreves tilbake via HTU.","If you agree, both confirm to the bank. If not, ask the bank for payout; the landlord has five weeks to document unpaid rent at the same bank or a case at HTU/the conciliation board. Without that, the bank must pay you. An unlawful deposit can be reclaimed via HTU."),e("Utbetaling og dokumentasjon","Payout and documentation"),"htuDeposit"]],ge="2026-10-19",r={before:e("Før bud og avtale","Before bid and contract"),during:e("Under handelen","During the transaction"),handover:e("Før overtakelse","Before handover"),after:e("Etter overtakelse","After handover")},n=(l,d,R,x,E,G,N,K,L,O,M,Y)=>({id:l,tracks:d.split(","),phase:R,title:x,term:E,definition:G,answer:N,who:K,when:L,action:O,ask:M,url:Y}),ke=[n("bud","buy,sell",r.before,e("Er budet mitt bindende?","Is my bid binding?"),e("Bud","Bid"),e("Et skriftlig tilbud om å kjøpe boligen til en pris, med akseptfrist.","A written offer to buy the home at a price, with an acceptance deadline."),e("Ja. Når budet er formidlet til selger, er du bundet til akseptfristen går ut, med mindre selger avslår. Aksepterer selger innen fristen, er avtalen inngått. Det finnes ingen angrerett ved kjøp av bolig. Ta derfor bare forbehold du virkelig trenger, og by ikke på flere boliger samtidig.","Yes. Once the bid is passed to the seller you are bound until the acceptance deadline expires, unless the seller rejects it. If the seller accepts within the deadline, the agreement is made. There is no cooling-off right when buying a home. So only add conditions you really need, and do not bid on several homes at once."),e("Kjøper, megler og selger","Buyer, agent and seller"),e("Før du sender første bud.","Before you send your first bid."),e("Sett maksimumspris og forbehold før budrunden","Set your maximum price and conditions before bidding"),e("Hvilken akseptfrist bør jeg sette, og hvordan formuleres et finansieringsforbehold?","What acceptance deadline should I set, and how is a financing condition worded?"),h),n("akseptfrist","buy,sell",r.before,e("Hvor kort kan akseptfristen være?","How short can the acceptance deadline be?"),e("Akseptfrist","Acceptance deadline"),e("Tidspunktet et bud faller bort hvis selger ikke har akseptert.","The time at which a bid lapses if the seller has not accepted."),e("I forbrukerkjøp skal megler ikke formidle bud med akseptfrist før kl. 12.00 første virkedag etter siste annonserte visning. Alle bud, budforhøyelser og aksepter skal være skriftlige, og du må legitimere deg ved første bud. Megler fører budjournal, som partene får etter salget.","In consumer sales the agent must not pass on bids with a deadline before 12:00 on the first working day after the last advertised viewing. All bids, raises and acceptances must be in writing, and you must identify yourself with your first bid. The agent keeps a bid journal, which the parties receive after the sale."),e("Megler","Agent"),e("Under budrunden.","During the bidding round."),e("Les meglers budregler i salgsoppgaven","Read the agent's bidding rules in the prospectus"),e("Hvordan bekrefter megler at budet mitt er mottatt, og når får jeg budjournalen?","How does the agent confirm receipt of my bid, and when do I get the bid journal?"),i),n("forbehold","buy",r.before,e("Kan jeg ta forbehold i budet?","Can I make my bid conditional?"),e("Forbehold","Condition"),e("Et vilkår i budet, f.eks. om finansiering eller salg av egen bolig.","A term in the bid, e.g. about financing or selling your own home."),e("Ja, men selger må akseptere det, og bud med forbehold blir normalt ikke akseptert før forbeholdet er avklart. Megler formidler ikke vilkår som skal holdes skjult for andre budgivere. Skaff finansieringsbevis på forhånd, så slipper du finansieringsforbehold i en konkurransesituasjon.","Yes, but the seller must accept it, and conditional bids are normally not accepted until the condition is cleared. The agent will not pass on terms meant to be hidden from other bidders. Get a financing certificate in advance so you can avoid a financing condition in a competitive round."),e("Kjøper og bank","Buyer and bank"),e("Før budet sendes.","Before the bid is sent."),e("Få finansieringsbevis og avklar forbehold med banken","Get a financing certificate and clear conditions with your bank"),e("Hva skjer hvis forbeholdet ikke blir oppfylt innen fristen?","What happens if the condition is not met by the deadline?"),h),n("kontrakt","buy,sell",r.during,e("Hva skjer etter akseptert bud?","What happens after an accepted bid?"),e("Kjøpekontrakt","Purchase contract"),e("Den skriftlige avtalen som bekrefter budet og regulerer gjennomføringen.","The written agreement confirming the bid and governing completion."),e("Bindende avtale foreligger allerede ved aksept; kontrakten skriver megler etterpå. Den skal gjengi pris, overtakelsesdato, løsøre, avtalte arbeider og oppgjør via klientkonto. Les den endelige versjonen og vedleggene, og få uklare punkter forklart før kontraktsmøtet.","A binding agreement already exists on acceptance; the agent drafts the contract afterwards. It must reflect price, handover date, contents, agreed works and settlement via the client account. Read the final version and attachments, and have unclear points explained before the contract meeting."),e("Megler, kjøper og selger","Agent, buyer and seller"),e("Mellom aksept og kontraktsmøte.","Between acceptance and the contract meeting."),e("Gå gjennom kontraktsutkastet med vedlegg","Review the draft contract with attachments"),e("Er alt fra budet og løsørelisten med, og hva skjer ved forsinket overtakelse?","Is everything from the bid and contents list included, and what happens if handover is delayed?"),i),n("tilstandsrapport","buy,sell",r.before,e("Hva betyr tilstandsrapporten for meg?","What does the condition report mean for me?"),e("Tilstandsrapport","Condition report"),e("En bygningssakkyndigs rapport om boligens tekniske tilstand etter forskriften.","A building surveyor's report on the home's technical condition under the regulation."),e("Siden 2022 kan boliger ikke selges «som den er» til forbrukere. Alt som er tydelig beskrevet i rapporten og salgsdokumentene, regnes som kjent for kjøper, selv om du ikke har lest det. Eldre boliger må forventes å ha feil. Kjøper dekker de første 10 000 kr av et mangelkrav selv.","Since 2022 homes cannot be sold 'as is' to consumers. Everything clearly described in the report and sales documents counts as known to the buyer, even if you did not read it. Older homes must be expected to have faults. The buyer bears the first NOK 10,000 of any defect claim."),e("Selger bestiller; kjøper leser","Seller orders; buyer reads"),e("Før bud; selger før annonsering.","Before bidding; seller before advertising."),e("Les tilstandsgrader og sjekk hva som er undersøkt","Read the condition grades and check what was examined"),e("Hvilke punkter har TG2 eller TG3, og hva vil utbedring koste?","Which items are graded TG2 or TG3, and what will repairs cost?"),F),n("megler","buy,sell",r.before,e("Er megleren min rådgiver?","Is the agent my adviser?"),e("Eiendomsmegler","Estate agent"),e("Et foretak med bevilling som formidler salget på oppdrag fra selger.","A licensed firm that handles the sale on the seller's instructions."),e("Megleren er engasjert og betalt av selger, men har omsorgsplikt og opplysningsplikt overfor begge parter og skal ikke gi råd som skader kjøper. Megler er likevel ikke din personlige rådgiver. Klager på megler går først til foretaket, deretter gratis til Reklamasjonsnemnda for Eiendomsmeglingstjenester.","The agent is engaged and paid by the seller but owes a duty of care and disclosure to both parties and must not advise in ways that harm the buyer. The agent is still not your personal adviser. Complaints go first to the firm, then free of charge to the Complaints Board for Estate Agency Services."),e("Megler; kjøper velger egen hjelp","Agent; the buyer chooses own help"),e("Før du binder deg.","Before you commit."),e("Avklar hva du vil ha egen hjelp til","Decide what you want your own help with"),e("Hvem kontrollerer dokumentene for meg, og hva dekker boligkjøperforsikring?","Who checks the documents for me, and what does buyer's insurance cover?"),I),n("boligkjoperforsikring","buy",r.during,e("Trenger jeg boligkjøperforsikring?","Do I need buyer's insurance?"),e("Boligkjøperforsikring","Buyer's insurance"),e("En forsikring som dekker juridisk bistand ved mangelkrav mot selger.","Insurance covering legal assistance for defect claims against the seller."),e("Den gir deg advokathjelp hvis du må reklamere mot selger eller selgers boligselgerforsikring, men gjør ikke boligen feilfri. Sjekk om innbo- eller husforsikringen din allerede har rettshjelp, og hva egenandelen er. Må normalt tegnes senest ved kontraktsignering.","It gives you legal help if you need to claim against the seller or the seller's insurer, but it does not make the home defect-free. Check whether your contents or building insurance already includes legal cover and what the excess is. It must normally be taken out by contract signing."),e("Kjøper","Buyer"),e("Før kontraktsmøtet.","Before the contract meeting."),e("Sammenlign boligkjøperforsikring med eksisterende rettshjelpsdekning","Compare buyer's insurance with existing legal cover"),e("Hva dekkes ikke, og hvor lenge gjelder forsikringen?","What is not covered, and how long does it last?"),p),n("boligselgerforsikring","sell",r.before,e("Bør jeg tegne boligselgerforsikring?","Should I take out seller's insurance?"),e("Boligselgerforsikring","Seller's insurance"),e("Forsikring som dekker selgers ansvar etter avhendingslova.","Insurance covering the seller's liability under the Sale of Property Act."),e("Forsikringen overtar reklamasjoner fra kjøper i fem år og betaler eventuell erstatning. Prisen er en prosentandel av salgssummen. Den forutsetter riktig egenerklæring; svarer du «nei» på noe du visste om, kan selskapet kreve regress. Den fritar deg ikke fra opplysningsplikten.","The insurer takes over buyer complaints for five years and pays any compensation. The price is a percentage of the sale price. It requires a correct seller's declaration; answering 'no' to something you knew about can lead to recourse. It does not remove your duty of disclosure."),e("Selger og megler","Seller and agent"),e("Før salget legges ut.","Before the home is listed."),e("Fyll ut egenerklæringen nøyaktig og sammenlign tilbud","Complete the declaration accurately and compare offers"),e("Hva koster det for min boligtype, og hva er unntatt?","What does it cost for my property type, and what is excluded?"),p),n("andel","buy,sell",r.before,e("Hva må jeg vite om borettslag?","What do I need to know about housing co-operatives?"),e("Forkjøpsrett og fellesgjeld","Right of first refusal and shared debt"),e("I borettslag eier du en andel med borett; laget eier bygningen og kan ha gjeld.","In a co-operative you own a share with a right to live there; the co-operative owns the building and may have debt."),e("Fellesgjelden er del av totalprisen og teller i bankens låneberegning; sjekk avdragsfrihet og sikringsordning for felleskostnader. Har laget forkjøpsrett, kan et medlem med lengre ansiennitet tre inn i budet ditt innen fristen (normalt 20 dager fra salgsmelding). Styret skal godkjenne ny andelseier, og utleie krever samtykke. Ingen dokumentavgift, men eierskiftegebyr.","Shared debt is part of the total price and counts in the bank's loan calculation; check interest-only periods and the guarantee scheme for common charges. If there is a right of first refusal, a member with longer seniority can step into your bid within the deadline (normally 20 days from notice of sale). The board must approve the new shareholder, and letting requires consent. No document tax, but a transfer fee."),e("Boligbyggelag, styret, megler og bank","Housing federation, board, agent and bank"),e("Før bud og til forkjøpsfristen er ute.","Before bidding and until the first-refusal deadline has passed."),e("Be om forkjøpsrettsavklaring og lagets regnskap","Ask for first-refusal clearance and the co-operative's accounts"),e("Er forkjøpsretten forhåndsavklart, og hva er min andel av fellesgjelden?","Has the right of first refusal been cleared in advance, and what is my share of the debt?"),P),n("ejerforening","buy,sell",r.before,e("Hvordan påvirker sameiet økonomien min?","How does the owners' association affect my finances?"),e("Sameie","Owners' association"),e("Eierseksjoner der du eier seksjonen og en andel av fellesarealene.","Condominium sections where you own the unit and a share of common areas."),e("Felleskostnadene dekker drift og vedlikehold av bygningen; regnskap, budsjett og årsmøtereferat viser planlagte arbeider som kan gi økte kostnader. Sameiet kan kreve tvangssalg ved manglende betaling. Du kan normalt leie ut fritt, men sjekk vedtektene. Dokumentavgift på 2,5 % gjelder.","Common charges cover running and maintaining the building; accounts, budget and AGM minutes show planned works that may raise costs. The association can force a sale for non-payment. You can normally let freely, but check the bylaws. Document tax of 2.5% applies."),e("Kjøper, megler og forretningsfører","Buyer, agent and manager"),e("Før bud.","Before bidding."),e("Les sameiets regnskap, budsjett og vedtekter","Read the association's accounts, budget and bylaws"),e("Er større arbeider vedtatt eller ventet, og hva blir min andel?","Are major works decided or expected, and what will my share be?"),v),n("skoede","buy,sell",r.during,e("Hva er tinglysing og dokumentavgift?","What are registration and document tax?"),e("Skjøte og tinglysing","Deed and registration"),e("Skjøtet overfører eiendomsretten; tinglysing hos Kartverket gir rettsvern.","The deed transfers ownership; registration with the Land Registry gives legal protection."),e("Megler tinglyser skjøtet og bankens pantedokument, vanligvis elektronisk samme dag. Kjøper betaler 2,5 % dokumentavgift av markedsverdien (minimum 250 kr) og tinglysingsgebyr per dokument; faktura forfaller 14 dager etter tinglysing. Ved nybygg beregnes avgiften bare av tomteverdien.","The agent registers the deed and the bank's mortgage deed, usually electronically the same day. The buyer pays 2.5% document tax on the market value (minimum NOK 250) plus a registration fee per document; the invoice is due 14 days after registration. For new builds the tax is calculated on the land value only."),e("Megler, Kartverket og bankene","Agent, Land Registry and banks"),e("Etter overtakelse; sjekk grunnboken etterpå.","After handover; check the land register afterwards."),e("Sett av penger til dokumentavgift og gebyr","Set aside money for document tax and fees"),e("Hvem sender dokumentene, og når får jeg fakturaen?","Who submits the documents, and when do I get the invoice?"),j),n("overtakelse","buy,sell",r.handover,e("Hva gjør vi på overtakelsesdagen?","What do we do on handover day?"),e("Overtakelsesprotokoll","Handover protocol"),e("Dokumentet partene fyller ut ved overtakelsen om boligens stand, nøkler og målere.","The document the parties complete at handover about the home's condition, keys and meters."),e("Kjøpesummen må stå på klientkonto før møtet. Gå gjennom boligen sammen: rengjøring, løsøre, nøkler, nye skader, tekniske anlegg og målerstander. Alt føres i protokollen, som oppgjørsavdelingen bruker for å frigi pengene. Ansvar og risiko går over til kjøper når nøklene er levert.","The purchase price must be in the client account before the meeting. Walk through the home together: cleaning, contents, keys, new damage, technical systems and meter readings. Everything goes in the protocol, which the settlement team uses to release the money. Responsibility and risk pass to the buyer when the keys are handed over."),e("Kjøper, selger og helst megler","Buyer, seller and ideally the agent"),e("På avtalt overtakelsesdato.","On the agreed handover date."),e("Sett av 90 minutter og ta med protokoll og kamera","Set aside 90 minutes and bring the protocol and a camera"),e("Hvem melder målerstandene, og hva gjør vi hvis vi er uenige?","Who reports the meter readings, and what do we do if we disagree?"),a),n("tilbakehold","buy,sell",r.handover,e("Kan jeg holde tilbake penger ved mangler?","Can I hold back money for defects?"),e("Tilbakehold","Holdback"),e("Et beløp som holdes igjen på meglers klientkonto til en mangel er avklart.","An amount held back in the agent's client account until a defect is resolved."),e("Ja. Ved mangler på overtakelsen kan kjøper holde tilbake et beløp, ensidig eller etter avtale. Beløpet føres i protokollen og blir stående på klientkonto. Tilbakehold sikrer pengene, men løser ikke problemet; dere må fortsatt avtale utbedring eller prisavslag. Ved dårlig vask kan selger ofte vaske på nytt dagen etter.","Yes. For defects at handover the buyer can hold back an amount, unilaterally or by agreement. The amount is recorded in the protocol and stays in the client account. A holdback secures the money but does not solve the problem; you still need to agree on repair or a price reduction. For poor cleaning the seller can often re-clean the next day."),e("Kjøper, selger og megler","Buyer, seller and agent"),e("På overtakelsen.","At handover."),e("Før beløp og begrunnelse i protokollen","Record the amount and reason in the protocol"),e("Hvor stort beløp er rimelig, og hvem bestemmer når det frigis?","What amount is reasonable, and who decides when it is released?"),a),n("mangler","buy",r.after,e("Hva gjør jeg hvis jeg oppdager en feil etter overtakelsen?","What if I find a fault after handover?"),e("Reklamasjon","Complaint"),e("En skriftlig melding til selger om at boligen har en mangel.","A written notice to the seller that the home has a defect."),e("Reklamer så snart du oppdager eller burde oppdaget feilen, senest innen fem år. Send til selger og selgers boligselgerforsikring, og ta vare på kopi. Du dekker de første 10 000 kr selv, og forhold som var opplyst, gir ikke krav. Uenighet med forsikringen kan prøves gratis i Finansklagenemnda; uten forsikring er forliksrådet første instans.","Complain as soon as you discover or should have discovered the fault, and within five years at most. Send it to the seller and the seller's insurer and keep a copy. You bear the first NOK 10,000, and disclosed matters give no claim. Disputes with the insurer can be tried free at the Financial Complaints Board; without insurance the conciliation board is the first step."),e("Kjøper, selger og selgers forsikring","Buyer, seller and the seller's insurer"),e("Straks feilen oppdages.","As soon as the fault is discovered."),e("Dokumenter feilen og send skriftlig reklamasjon","Document the fault and send a written complaint"),e("Står forholdet i tilstandsrapporten, og hva koster utbedringen?","Is the matter in the condition report, and what will repairs cost?"),c),n("oppgjor","sell",r.after,e("Når får jeg pengene fra salget?","When do I get the money from the sale?"),e("Oppgjør","Settlement"),e("Meglers utbetaling av salgssummen etter at skjøtet er tinglyst.","The agent's payout of the sale price after the deed is registered."),e("Kjøper betaler til meglers klientkonto før overtakelsen. Etter signert protokoll innfrir megler lånet ditt, sletter pant og tinglyser skjøtet. Du får normalt resten én til to uker etter overtakelsen, når skjøtet er i retur. Nøkkeloverlevering er ikke i seg selv en utbetaling.","The buyer pays into the agent's client account before handover. After the signed protocol the agent redeems your loan, deletes the mortgage and registers the deed. You normally get the balance one to two weeks after handover, when the deed is returned. Handing over keys is not in itself a payout."),e("Megler og selgers bank","Agent and the seller's bank"),e("Rundt overtakelsen.","Around handover."),e("Be megler bekrefte forventet utbetalingsdato","Ask the agent to confirm the expected payout date"),e("Hva trekkes fra, og hva skjer med tilbakeholdt beløp?","What is deducted, and what happens to any holdback?"),a),n("strom","common",r.handover,e("Må jeg velge strømavtalen i overtakelsesprotokollen?","Do I have to pick the power contract in the handover protocol?"),e("Leveringsplikt","Supply obligation"),e("Nettselskapets midlertidige strømleveranse til kunder uten kraftavtale.","The grid company's temporary power supply to customers without a contract."),e("Nei. Du kan avslå strømavtalene som tilbys i protokollen, og megler kan ikke bestille strøm for deg uten fullmakt. Nettleie følger boligen; kraftleverandør velger du fritt, f.eks. via strompris.no. Velger du ingen, får du leveringspliktig strøm fra nettselskapet, som blir dyrere etter seks uker. En ny avtale kan tilbakedateres inntil 30 dager.","No. You can decline the power contracts offered in the protocol, and the agent cannot order power for you without authority. The grid fee follows the home; the supplier is your free choice, e.g. via strompris.no. If you choose none, you get supply-obligation power from the grid company, which becomes more expensive after six weeks. A new contract can be backdated up to 30 days."),e("Deg og kraftleverandøren","You and the power supplier"),e("Før eller like etter overtakelse/innflytting.","Before or just after handover/move-in."),e("Bestill en åpen spotprisavtale fra overtakelsesdatoen","Order an open spot-price contract from the handover date"),e("Er avtalen uten binding, og hva er påslaget per kWh?","Is the contract without lock-in, and what is the mark-up per kWh?"),S),n("flyttemelding","common",r.after,e("Når må jeg melde flytting?","When must I report my move?"),e("Flyttemelding","Move notice"),e("Registrering av ny bostedsadresse i Folkeregisteret.","Registration of your new residential address in the Population Register."),e("Flyttemelding sendes tidligst 31 dager før og senest 8 dager etter at du har flyttet, gratis på skatteetaten.no. Bruk datoen du faktisk bor på adressen, ikke overtakelsesdatoen. Elever og studenter kan velge å la være. Posten-ettersending bestilles separat eller i samme skjema.","The notice is sent at the earliest 31 days before and no later than 8 days after you move, free on skatteetaten.no. Use the date you actually live at the address, not the handover date. Pupils and students may choose not to. Posten forwarding is ordered separately or in the same form."),e("Deg og Skatteetaten","You and Skatteetaten"),e("Senest 8 dager etter flytting.","No later than 8 days after moving."),e("Meld flytting på skatteetaten.no","Report the move on skatteetaten.no"),e("Hvilken dato tar jeg faktisk bolig på adressen?","On what date do I actually take up residence at the address?"),o),n("fastlege","common",r.after,e("Må jeg bytte fastlege når jeg flytter?","Do I have to change GP when I move?"),e("Fastlege","Regular GP"),e("Legen du er registrert hos i fastlegeordningen.","The doctor you are registered with in the GP scheme."),e("Nei. Du kan beholde fastlegen selv om du flytter til en annen kommune. Vil du bytte, gjør du det på Helsenorge til en lege med ledig plass; byttet gjelder fra den første i neste måned. Du kan bytte to ganger per år, og i tillegg når du har meldt flytting. Du må selv be om å få journalen overført.","No. You can keep your GP even if you move to another municipality. If you want to switch, do it on Helsenorge to a doctor with free capacity; the change applies from the first of the next month. You can switch twice a year, plus once after reporting a move. You must ask for your records to be transferred yourself."),e("Deg og Helsenorge","You and Helsenorge"),e("Når det passer deg.","Whenever it suits you."),e("Sjekk ledige fastleger nær ny adresse","Check available GPs near the new address"),e("Har legen ledig plass, og kan barna få samme lege?","Does the doctor have capacity, and can the children get the same GP?"),m),n("depositum","rentIn,rentOut",r.before,e("Hvor stort kan depositumet være, og hvor skal det stå?","How large can the deposit be, and where must it be held?"),e("Depositum","Deposit"),e("Sikkerhet for utleiers krav ved leieforholdets slutt.","Security for the landlord's claims at the end of the tenancy."),e("Depositum kan maksimalt tilsvare seks måneders husleie og må avtales ved kontraktsinngåelse. Det skal stå på egen depositumskonto i leietakers navn, der ingen kan ta ut penger alene; utleier betaler gebyret og leietaker får rentene. Betaling til utleiers egen konto eller kontant er ulovlig, og pengene kan kreves tilbake.","The deposit may be at most six months' rent and must be agreed at signing. It must sit in a separate deposit account in the tenant's name, which neither party can draw on alone; the landlord pays the fee and the tenant gets the interest. Payment to the landlord's own account or in cash is unlawful and the money can be reclaimed."),e("Leietaker, utleier og banken","Tenant, landlord and bank"),e("Før innbetaling.","Before paying."),e("Få bankens bekreftelse på depositumskontoen","Get the bank's confirmation of the deposit account"),e("Står kontoen i mitt navn, og er depositumet nevnt i kontrakten?","Is the account in my name, and is the deposit mentioned in the lease?"),f),n("depositum-tilbake","rentOut",r.after,e("Hvordan får jeg depositumet tilbake?","How do I get my deposit back?"),e("Utbetaling av depositum","Deposit release"),e("Bankens frigivelse av depositumskontoen etter leieforholdet.","The bank's release of the deposit account after the tenancy."),e("Er dere enige, bekrefter begge til banken. Hvis ikke, ber du banken om utbetaling. Banken varsler utleier, som har fem uker på å dokumentere ubetalt leie i samme bank eller en sak hos HTU eller forliksrådet. Ellers skal banken betale ut til deg. Alle andre krav må utleier få dom på eller ditt samtykke til.","If you agree, both confirm to the bank. If not, ask the bank for payout. The bank notifies the landlord, who has five weeks to document unpaid rent at the same bank or a case at HTU or the conciliation board. Otherwise the bank must pay you. All other claims require a judgment or your consent."),e("Leietaker, bank og utleier","Tenant, bank and landlord"),e("Rett etter utflytting.","Right after moving out."),e("Send skriftlig krav om utbetaling til banken","Send a written payout request to the bank"),e("Har banken varslet utleier, og når utløper femukersfristen?","Has the bank notified the landlord, and when does the five-week deadline expire?"),b),n("innflytting","rentIn",r.handover,e("Hvordan dokumenterer jeg boligens stand ved innflytting?","How do I document the condition at move-in?"),e("Innflyttingsprotokoll","Move-in protocol"),e("Et dokument om tilstand, innhold, nøkler og målere ved innflytting.","A document on condition, contents, keys and meters at move-in."),e("Gå gjennom boligen med utleier og fyll ut en overtakelsesprotokoll for utleie. Ta daterte bilder av alle skader og legg dem ved kontrakten. Meld mangler skriftlig så snart du oppdager dem. Protokollen avgjør ofte depositumstvister ved utflytting.","Walk through the home with the landlord and complete a rental handover protocol. Take dated photos of all damage and attach them to the lease. Report defects in writing as soon as you discover them. The protocol often decides deposit disputes at move-out."),e("Leietaker og utleier","Tenant and landlord"),e("På innflyttingsdagen.","On move-in day."),e("Fyll ut protokoll og ta bilder før du pakker ut","Complete the protocol and take photos before unpacking"),e("Har utleier mottatt mangellisten min skriftlig?","Has the landlord received my list of defects in writing?"),w),n("oppsigelse","rentOut",r.before,e("Hvor lang er oppsigelsestiden min?","How long is my notice period?"),e("Oppsigelsestid","Notice period"),e("Tiden fra oppsigelsen til leieforholdet opphører.","The time from giving notice until the tenancy ends."),e("Lovens hovedregel er tre måneder, regnet til utløpet av en kalendermåned, med mindre kontrakten sier noe annet; for hybel er det én måned. Leietaker kan si opp uten begrunnelse, men gjør det skriftlig. En tidsbestemt avtale kan normalt ikke sies opp før utløp uten at det er avtalt. Å flytte ut tidligere stopper ikke husleien.","The statutory default is three months, counted to the end of a calendar month, unless the lease says otherwise; for a room in the landlord's home it is one month. A tenant can give notice without a reason, but do it in writing. A fixed-term lease normally cannot be ended early unless agreed. Moving out earlier does not stop the rent."),e("Leietaker og utleier","Tenant and landlord"),e("Før du binder flyttedato til utgifter.","Before you tie a moving date to expenses."),e("Les oppsigelsespunktet i kontrakten og send skriftlig oppsigelse","Read the notice clause in the lease and give written notice"),e("Hvilken dato hefter jeg til, og kan utleier leie ut tidligere?","Until what date am I liable, and can the landlord re-let earlier?"),y),n("tidsbestemt","rentIn",r.before,e("Hva betyr tidsbestemt leieavtale?","What does a fixed-term lease mean?"),e("Tidsbestemt avtale","Fixed-term lease"),e("En leieavtale som opphører på en avtalt dato uten oppsigelse.","A lease that ends on an agreed date without notice."),e("Ved tidsbestemt avtale er begge bundet til sluttdatoen, med mindre kontrakten gir rett til oppsigelse i leietiden. Ved tidsubestemt avtale løper leien til en av partene sier opp. Sjekk hvilken type du har, og om leien kan justeres: KPI én gang i året med én måneds varsel, og tilpasning til gjengs leie tidligst etter to og et halvt år.","With a fixed term both parties are bound until the end date, unless the lease allows notice during the term. With an open-ended lease the tenancy runs until one party gives notice. Check which type you have and how rent can be adjusted: CPI once a year with one month's notice, and adjustment to market rent at the earliest after two and a half years."),e("Leietaker og utleier","Tenant and landlord"),e("Før signering.","Before signing."),e("Sjekk leietid og oppsigelsesadgang i kontrakten","Check the term and notice rights in the lease"),e("Kan jeg si opp i leietiden, og hva skjer når perioden utløper?","Can I give notice during the term, and what happens when it expires?"),J),n("htu","rentIn,rentOut",r.after,e("Hvor klager jeg på utleier eller leietaker?","Where do I complain about a landlord or tenant?"),e("Husleietvistutvalget (HTU)","Rent Disputes Tribunal (HTU)"),e("Et rimelig tvisteløsningsorgan for leieforhold i hele landet.","A low-cost dispute body for tenancies throughout Norway."),e("HTU behandler tvister om husleie, depositum, mangler, oppsigelse og flyttevask i hele Norge. Klagen sendes digitalt med dokumentasjon; gebyret er lavt for leietaker og høyere for utleier. Saker løses ved mekling eller vedtak, men ventetiden kan være lang, så send inn tidlig og dokumenter godt.","HTU handles disputes about rent, deposits, defects, termination and move-out cleaning throughout Norway. The complaint is filed digitally with documentation; the fee is low for tenants and higher for landlords. Cases are resolved by mediation or decision, but waiting times can be long, so file early and document well."),e("Leietaker eller utleier","Tenant or landlord"),e("Når dere ikke blir enige.","When you cannot agree."),e("Samle kontrakt, protokoll, bilder og korrespondanse i én PDF","Gather lease, protocol, photos and correspondence in one PDF"),e("Har jeg prøvd å løse saken skriftlig med motparten først?","Have I tried to resolve the matter in writing with the other party first?"),z)],he=[[e("Mellomleie mellom salg og kjøp","Temporary rental between selling and buying"),e("Hold alle forløp aktive samtidig og registrer hver adresse og overtakelsesdato for seg. Legg dobbel boutgift, ekstra flytting og lagring inn i budsjettet. Si ikke opp leieboligen på bakgrunn av en forventet kjøpsdato, og husk at forkjøpsrett i borettslag kan endre planen.","Keep all tracks active at once and record each address and handover date separately. Budget for double housing costs, an extra move and storage. Do not give notice on your rental based on an expected purchase date, and remember that first-refusal rights in a co-operative can change the plan.")],[e("Leie: inn og ut","Renting: in and out"),e("Bruk Forbrukerrådets husleiekontrakt, krev depositumskonto i ditt navn og fyll ut protokoll med bilder ved både inn- og utflytting. Boligen skal leveres ryddet og rengjort. Tvister går til Husleietvistutvalget.","Use the Consumer Council's lease, insist on a deposit account in your name and complete a protocol with photos at both move-in and move-out. The home must be returned tidy and clean. Disputes go to the Rent Disputes Tribunal.")],[e("Budrunden","The bidding round"),e("Bud er bindende, og det finnes ingen angrerett. Bestem maksimumspris før runden starter, skaff finansieringsbevis og sett en realistisk akseptfrist. Vurder hele pakken: pris, overtakelsesdato og hva som følger med.","Bids are binding and there is no cooling-off right. Decide your maximum price before the round starts, get a financing certificate and set a realistic acceptance deadline. Weigh the whole package: price, handover date and what is included.")],[e("Løsøre og tilbehør","Contents and fittings"),e("Skriv nøyaktig hva som følger med, f.eks. hvitevarer, gardiner, lamper, ladeboks og hageutstyr. Beskriv stand og eventuell egen pris, og skill mellom eide og leasede ting. Få listen inn i kontrakten og sjekk den på overtakelsen.","Write down exactly what is included, e.g. appliances, curtains, lamps, EV charger and garden equipment. Describe condition and any separate price, and distinguish owned from leased items. Get the list into the contract and check it at handover.")],[e("Overtakelse og tilbakehold","Handover and holdback"),e("Hold overtakelsesdag og flyttedag adskilt. Pengene skal være på klientkonto før møtet, og ansvaret går over når nøklene leveres. Uenigheter føres i protokollen; større beløp kan holdes tilbake, men problemet må fortsatt løses.","Keep the handover day and moving day separate. The money must be in the client account before the meeting, and responsibility passes when the keys are handed over. Disagreements go in the protocol; larger amounts can be held back, but the problem still has to be solved.")],[e("Forkjøpsrett i borettslag","First refusal in co-operatives"),e("Spør om forkjøpsretten er forhåndsavklart. Er den ikke det, kan et medlem med lengre ansiennitet tre inn i budet ditt innen fristen, og du er løst fra avtalen. Ikke bind deg til salg eller oppsigelse før fristen er ute.","Ask whether the right of first refusal has been cleared in advance. If not, a member with longer seniority can step into your bid within the deadline, releasing you from the agreement. Do not commit to a sale or notice before the deadline has passed.")],[e("Forbehold og frister","Conditions and deadlines"),e("Finansieringsforbehold, forkjøpsrettsfrist og reklamasjonsfrister er forskjellige ting. Stol på de datoene megler, bank og boligbyggelag bekrefter skriftlig; appen beregner dem ikke.","Financing conditions, first-refusal deadlines and complaint deadlines are different things. Rely on the dates the agent, bank and housing federation confirm in writing; the app does not calculate them.")],[e("Når er vi helt ferdige?","When are we really done?"),e("Akseptert bud, signert kontrakt, overtakelse, tinglysing og oppgjør er ulike milepæler. Sjekk grunnboken etter tinglysing og oppgjørsoppstillingen etter utbetaling. Din markering i appen endrer ikke handelens juridiske status.","Accepted bid, signed contract, handover, registration and settlement are separate milestones. Check the land register after registration and the settlement statement after payout. Ticking a box in the app does not change the legal status of the deal.")]],ue={intro:[[e("Eiendomsmegler","Estate agent"),e("gjennomfører salget, budrunden, kontrakt og oppgjør; har omsorgsplikt for begge parter","runs the sale, bidding, contract and settlement; owes a duty of care to both parties")],[e("Bank","Bank"),e("finansieringsbevis, lån og utbetaling mot pant","financing certificate, loan and disbursement against mortgage")],[e("Bygningssakkyndig / takstmann","Building surveyor"),e("tilstandsrapport og egen teknisk befaring","condition report and your own technical inspection")],[e("Advokat","Lawyer"),e("kompliserte avtaler, reklamasjon og tvister","complex agreements, complaints and disputes")],[e("Forretningsfører / boligbyggelag","Manager / housing federation"),e("forkjøpsrett, godkjenning, felleskostnader og eierskifte i borettslag","first refusal, approval, common charges and share transfer in co-operatives")],[e("Leieboerforeningen / HTU","Tenants' association / HTU"),e("leiekontrakt, depositum, oppsigelse og tvister i leieforhold","lease, deposit, notice and tenancy disputes")]],links:[{href:T,title:e("Sjekkliste før du velger megler","Checklist before choosing an agent"),description:e("Forbrukerrådets råd om tilbud, honorar og oppdragsavtale","The Consumer Council's advice on quotes, fees and the engagement agreement")},{href:A,title:e("Sjekkliste før du kjøper bolig","Checklist before buying a home"),description:e("Finansieringsbevis, dokumenter, visning og budrunde","Financing certificate, documents, viewing and bidding")},{href:i,title:e("Finanstilsynet om eiendomsmegling","The FSA on estate agency"),description:e("Meglers plikter, budregler og klagemuligheter","Agents' duties, bidding rules and how to complain")},{href:I,title:e("Klage på eiendomsmegler","Complain about an estate agent"),description:e("Veien til Reklamasjonsnemnda for Eiendomsmeglingstjenester (gratis)","The route to the Complaints Board for Estate Agency Services (free)")},{href:C,title:e("Husleietvistutvalget (HTU)","Rent Disputes Tribunal (HTU)"),description:e("Tvisteløsning for leieforhold i hele landet","Dispute resolution for tenancies throughout Norway")},{href:B,title:e("Bostøtte hos Husbanken","Housing allowance at Husbanken"),description:e("Søk på nytt etter flytting og meld endringer","Re-apply after moving and report changes")},{href:D,title:e("Sjekkliste før du velger strømavtale","Checklist before choosing a power contract"),description:e("Forbrukerrådets råd og prissammenligning på strompris.no","The Consumer Council's advice and price comparison on strompris.no")}]};export{ke as adviceArticles,ge as adviceReviewed,ue as advisers,ie as checklist,oe as meta,se as profileOptions,he as tips,de as tradeRows,le as tradeSources};
